window.DQ=window.DQ||{};DQ["tefila"]={"a":[["יוֹסֵף פָּקַח אֶת עֵינָיו בַּבֹּקֶר. מָה טוֹב לוֹמַר מִיָּד?",["בִּרְכַּת הַמָּזוֹן","מוֹדֶה אֲנִי לְפָנֶיךָ","קְרִיאַת שְׁמַע שֶׁל לַיְלָה"],1,"מִיָּד כְּשֶׁקָּמִים אוֹמְרִים \"מוֹדֶה אֲנִי\" – תּוֹדָה לַה׳ שֶׁהֶחֱזִיר לָנוּ אֶת הַנְּשָׁמָה.","פֶּרֶק ז׳, הֲלָכָה א׳","בֹּקֶר טוֹב לַה׳"],["אֵיךְ נוֹטְלִים יָדַיִם בַּבֹּקֶר?",["כָּל יָד פַּעַם אַחַת","רַק יַד יָמִין, שָׁלֹשׁ פְּעָמִים","יָמִין וּשְׂמֹאל, שָׁלֹשׁ פְּעָמִים לְסֵרוּגִין"],2,"נוֹטְלִים יָמִין, שְׂמֹאל – וְחוֹזְרִים עַל זֶה שָׁלֹשׁ פְּעָמִים. כָּךְ כָּל יָד נִטֶּלֶת שָׁלֹשׁ פְּעָמִים.","פֶּרֶק ח׳, הֲלָכָה ב׳","בֹּקֶר טוֹב לַה׳"],["דָּנִי עוֹד לֹא נָטַל יָדַיִם. בְּמָה אָסוּר לוֹ לִגֹּעַ?",["בָּעֵינַיִם","בַּשְּׂמִיכָה","בַּנַּטְלָה"],0,"לִפְנֵי הַנְּטִילָה לֹא נוֹגְעִים בָּעֵינַיִם, בַּפֶּה, בָּאַף וּבָאָזְנַיִם – וְגַם לֹא בְּאֹכֶל.","פֶּרֶק ח׳, הֲלָכָה ב׳","בֹּקֶר טוֹב לַה׳"],["אֵיזוֹ נַעַל נוֹעֲלִים רִאשׁוֹנָה?",["אֶת הַשְּׂמָאלִית","אֶת שְׁתֵּיהֶן יַחַד","אֶת הַיְּמָנִית"],2,"נוֹעֲלִים קֹדֶם אֶת הַיְּמָנִית, וְקוֹשְׁרִים קֹדֶם אֶת הַשְּׂמָאלִית.","פֶּרֶק ז׳, הֲלָכָה ג׳","בֹּקֶר טוֹב לַה׳"],["עַל מָה מְבָרְכִים \"עוֹטֵר יִשְׂרָאֵל בְּתִפְאָרָה\"?",["עַל נְעִילַת הַנַּעֲלַיִם","עַל כִּסּוּי הָרֹאשׁ","עַל פְּקִיחַת הָעֵינַיִם"],1,"\"עוֹטֵר יִשְׂרָאֵל בְּתִפְאָרָה\" – עַל הַכִּפָּה וְהַכּוֹבַע. \"שֶׁעָשָׂה לִי כָּל צָרְכִּי\" – עַל הַנַּעֲלַיִם, וּ\"פוֹקֵחַ עִוְרִים\" – עַל הָעֵינַיִם.","פֶּרֶק ט׳, הֲלָכָה א׳","בֹּקֶר טוֹב לַה׳"],["מָתַי אוֹמְרִים אֶת הַבְּרָכָה \"עַל נְטִילַת יָדַיִם\"?",["לִפְנֵי שֶׁשּׁוֹפְכִים מַיִם","אַחֲרֵי הַנִּגּוּב בַּמַּגֶּבֶת","אַחֲרֵי הַנְּטִילָה, לִפְנֵי הַנִּגּוּב"],2,"מְבָרְכִים אַחֲרֵי הַנְּטִילָה – כְּשֶׁהַיָּדַיִם כְּבָר נְקִיּוֹת – וְעוֹד לִפְנֵי שֶׁמְּנַגְּבִים אוֹתָן.","פֶּרֶק ח׳, הֲלָכָה ד׳","בֹּקֶר טוֹב לַה׳"],["כַּמָּה גְּבָרִים צְרִיכִים כְּדֵי שֶׁיִּהְיֶה מִנְיָן?",["שְׁלֹשָׁה","שִׁבְעָה","עֲשָׂרָה"],2,"מִנְיָן הוּא עֲשָׂרָה גְּבָרִים מִגִּיל בַּר מִצְוָה. כְּשֶׁהֵם מִתְפַּלְּלִים יַחַד – הַשְּׁכִינָה שׁוֹרָה בֵּינֵיהֶם.","פֶּרֶק ב׳, הֲלָכוֹת א׳, ו׳","בָּאִים לְבֵית ה׳"],["בְּסוֹף הַתְּפִלָּה מְנַחֵם יוֹצֵא מִבֵּית הַכְּנֶסֶת. אֵיךְ נָכוֹן לָצֵאת?",["הוֹלֵךְ לְאַט","רָץ מַהֵר הַחוּצָה","קוֹפֵץ בְּשִׂמְחָה"],0,"לְבֵית הַכְּנֶסֶת רָצִים, וּמִמֶּנּוּ יוֹצְאִים לְאַט – שֶׁלֹּא יֵרָאֶה כְּאִלּוּ שְׂמֵחִים לְהִפָּרֵד מִמֶּנּוּ.","פֶּרֶק ג׳, הֲלָכָה א׳","בָּאִים לְבֵית ה׳"],["מָה טוֹב לַעֲשׂוֹת רֶגַע לִפְנֵי הַתְּפִלָּה?",["לְסַפֵּר בְּדִיחָה","לָתֵת צְדָקָה","לִבְדֹּק הוֹדָעוֹת"],1,"טוֹב לָתֵת צְדָקָה לִפְנֵי הַתְּפִלָּה. צְחוֹק וְדִבּוּרִים בְּטֵלִים מַרְחִיקִים אֶת הַלֵּב, וְאֶת הַטֶּלֶפוֹן מְכַבִּים לִפְנֵי הַתְּפִלָּה.","פֶּרֶק ה׳, הֲלָכוֹת א׳, ז׳","בָּאִים לְבֵית ה׳"],["אֵיזֶה לְבוּשׁ מַתְאִים לִתְפִלָּה?",["פִּיגָ׳מָה","בְּגָדִים מְלֻכְלָכִים","בְּגָדִים נְקִיִּים"],2,"בַּתְּפִלָּה עוֹמְדִים לִפְנֵי הַמֶּלֶךְ, וְלָכֵן לוֹבְשִׁים בְּגָדִים מְכֻבָּדִים. בְּפִיגָ׳מָה אוֹ בִּבְגָדִים מְלֻכְלָכִים לֹא בָּאִים אֲפִלּוּ לִפְנֵי אָדָם חָשׁוּב.","פֶּרֶק ה׳, הֲלָכוֹת ד׳–ה׳","בָּאִים לְבֵית ה׳"],["יְהוּדָה הִגִּיעַ לְבֵית הַכְּנֶסֶת, וְהוּא צָרִיךְ לַשֵּׁרוּתִים. מָה יַעֲשֶׂה?",["יֵלֵךְ קֹדֶם לַשֵּׁרוּתִים","יִתְפַּלֵּל וְיִתְאַפֵּק","יִתְפַּלֵּל מַהֵר מְאוֹד"],0,"מִי שֶׁצָּרִיךְ לַשֵּׁרוּתִים הוֹלֵךְ לִפְנֵי הַתְּפִלָּה. כָּךְ הוּא עוֹמֵד לִפְנֵי ה׳ נָקִי, וְהַלֵּב פָּנוּי לְכַוָּנָה.","פֶּרֶק ה׳, הֲלָכָה ח׳","בָּאִים לְבֵית ה׳"],["מָתַי כְּדַאי לְהַגִּיעַ לִתְפִלַּת שַׁחֲרִית?",["בְּאֶמְצַע הַתְּפִלָּה","מֻקְדָּם, עִם הָרִאשׁוֹנִים","בְּסוֹף הַתְּפִלָּה"],1,"כְּדַאי לִהְיוֹת בֵּין עֲשָׂרָה הָרִאשׁוֹנִים, שֶׁבִּזְכוּתָם הַשְּׁכִינָה שׁוֹרָה. וְהַמַּקְדִּים לְשַׁחֲרִית זוֹכֶה לַאֲרִיכוּת יָמִים.","פֶּרֶק ב׳, הֲלָכָה א׳; פֶּרֶק ג׳, הֲלָכָה א׳","בָּאִים לְבֵית ה׳"],["אֵיפֹה נָכוֹן לְדָנִי לַעֲמֹד בִּתְפִלַּת שְׁמוֹנֶה עֶשְׂרֵה?",["מוּל מַרְאָה גְּדוֹלָה","מוּל צִיּוּרִים עַל הַקִּיר","מוּל קִיר חָלָק"],2,"מוּל מַרְאָה אָסוּר לְהִתְפַּלֵּל – זֶה נִרְאֶה כְּמוֹ הִשְׁתַּחֲוָיָה לַבָּבוּאָה. וּמוּל צִיּוּרִים לֹא מִתְפַּלְּלִים, כִּי הֵם מַסִּיחִים אֶת הַדַּעַת. הֲכִי טוֹב – מוּל קִיר שֶׁאֵין עָלָיו דָּבָר שֶׁמַּפְרִיעַ.","פֶּרֶק ג׳, הֲלָכָה ו׳","בָּאִים לְבֵית ה׳"],["בַּטִּיּוּל הִגִּיעַ זְמַן מִנְחָה. אֵיפֹה עָדִיף שֶׁאָבִי יִתְפַּלֵּל שְׁמוֹנֶה עֶשְׂרֵה?",["בֵּין הָעֵצִים","בְּאֶמְצַע שָׂדֶה פָּתוּחַ","לְיַד פַּח הָאַשְׁפָּה"],0,"בְּשֶׁטַח פָּתוּחַ הַמַּחְשָׁבָה מִתְפַּזֶּרֶת, וְלָכֵן מִי שֶׁבַּדֶּרֶךְ מִתְפַּלֵּל בֵּין הָעֵצִים אוֹ לְיַד קִיר. וּמִפַּחֵי אַשְׁפָּה שֶׁיֵּשׁ לָהֶם רֵיחַ רַע – מִתְרַחֲקִים.","פֶּרֶק ג׳, הֲלָכוֹת ח׳, י׳","בָּאִים לְבֵית ה׳"],["בְּמָה רָאוּי לִפְתֹּחַ אֶת הַתְּפִלָּה?",["בִּרְשִׁימַת בַּקָּשׁוֹת","בְּשִׁירֵי שֶׁבַח לַה׳","בְּשִׂיחָה עִם חָבֵר"],1,"כְּמוֹ מֹשֶׁה רַבֵּנוּ – קֹדֶם מְשַׁבְּחִים אֶת ה׳ בִּפְסוּקֵי דְּזִמְרָה, וְרַק אַחַר כָּךְ מְבַקְּשִׁים.","פֶּרֶק י״ד, הֲלָכָה א׳","שָׁרִים וּמַמְלִיכִים"],["מֵאִיר בְּאֶמְצַע פְּסוּקֵי דְּזִמְרָה, וְחָבֵר שׁוֹאֵל אוֹתוֹ מָה הַשָּׁעָה. מָה יַעֲשֶׂה?",["יַמְשִׁיךְ לְהִתְפַּלֵּל בְּלִי לְדַבֵּר","יַעֲנֶה לוֹ בְּקוֹל","יֵצֵא אִתּוֹ הַחוּצָה"],0,"מִ\"בָּרוּךְ שֶׁאָמַר\" וְעַד \"יִשְׁתַּבַּח\" הַכֹּל יְחִידָה אַחַת, וְלֹא מַפְסִיקִים בְּדִבּוּר. אֶת הַחָבֵר אֶפְשָׁר לַעֲנוֹת אַחֲרֵי הַתְּפִלָּה.","פֶּרֶק י״ד, הֲלָכָה ד׳","שָׁרִים וּמַמְלִיכִים"],["רְאוּבֵן הִגִּיעַ לַפָּסוּק \"שְׁמַע יִשְׂרָאֵל\". מָה הוּא עוֹשֶׂה?",["מַבִּיט סָבִיב בְּבֵית הַכְּנֶסֶת","סוֹגֵר אֶת הַסִּדּוּר","מְכַסֶּה אֶת הָעֵינַיִם בְּיַד יָמִין"],2,"מְכַסִּים אֶת הָעֵינַיִם בְּיַד יָמִין, כְּדֵי שֶׁשּׁוּם דָּבָר לֹא יַפְרִיעַ לְכַוָּנָה בְּקַבָּלַת עֹל מַלְכוּת שָׁמַיִם.","פֶּרֶק ט״ו, הֲלָכָה ו׳","שָׁרִים וּמַמְלִיכִים"],["אֵיךְ אוֹמְרִים \"בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד\"?",["בְּלַחַשׁ","בְּקוֹל רָם מְאוֹד","בְּשִׁירָה עִם כָּל הַקָּהָל"],0,"אֶת הַמִּשְׁפָּט שֶׁאָמַר יַעֲקֹב אָבִינוּ אוֹמְרִים בְּלַחַשׁ, כִּי הוּא לֹא כָּתוּב בַּתּוֹרָה.","פֶּרֶק ט״ו, הֲלָכָה ז׳","שָׁרִים וּמַמְלִיכִים"],["אֵיךְ נָכוֹן לִקְרֹא קְרִיאַת שְׁמַע?",["מַהֵר מְאוֹד, כְּדֵי לְהַסְפִּיק","לְאַט, וְכָל אוֹת בְּרוּרָה","רַק בַּמַּחֲשָׁבָה, בְּלִי פֶּה"],1,"מְדַקְדְּקִים בְּכָל אוֹת וּמַשְׁמִיעִים לָאֹזֶן. מִי שֶׁרַק חָשַׁב בַּלֵּב וְלֹא אָמַר בַּפֶּה – לֹא יָצָא.","פֶּרֶק ט״ו, הֲלָכָה ט׳","שָׁרִים וּמַמְלִיכִים"],["יוֹסִי הוֹלֵךְ בַּדֶּרֶךְ וּמַגִּיעַ לַפָּסוּק הָרִאשׁוֹן שֶׁל שְׁמַע. מָה יַעֲשֶׂה?",["יָרוּץ מַהֵר לְבֵית הַכְּנֶסֶת","יַמְשִׁיךְ לָלֶכֶת","יַעֲמֹד בִּמְקוֹמוֹ"],2,"מְקַבְּלִים עֹל מַלְכוּת שָׁמַיִם בְּכָבוֹד, לֹא בְּדֶרֶךְ אַגַּב. לָכֵן עוֹמְדִים בַּפָּסוּק הָרִאשׁוֹן.","פֶּרֶק ט״ו, הֲלָכָה י׳","שָׁרִים וּמַמְלִיכִים"],["אֵיךְ עוֹמְדִים בִּשְׁמוֹנֶה עֶשְׂרֵה?",["רַגְלַיִם פְּתוּחוֹת לִרְוָחָה","רַגְלַיִם צְמוּדוֹת כְּמוֹ רֶגֶל אַחַת","נִשְׁעָנִים עַל הַקִּיר"],1,"מַצְמִידִים אֶת הָרַגְלַיִם לְכָל הָאֹרֶךְ, כְּמוֹ הַמַּלְאָכִים: \"וְרַגְלֵיהֶם רֶגֶל יְשָׁרָה\". וְלֹא נִשְׁעָנִים – כִּי מִי שֶׁנִּשְׁעָן לֹא עוֹמֵד בְּיִרְאָה לִפְנֵי הַמֶּלֶךְ.","פֶּרֶק י״ז, הֲלָכָה ד׳","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["יְהוּדָה גָּר בְּאֶרֶץ יִשְׂרָאֵל. לְאָן יִפְנֶה בִּשְׁמוֹנֶה עֶשְׂרֵה?",["לְכִוּוּן יְרוּשָׁלַיִם","לְכִוּוּן הַשֶּׁמֶשׁ הַזּוֹרַחַת","לְכִוּוּן הַחַלּוֹן הַקָּרוֹב"],0,"בִּשְׁמוֹנֶה עֶשְׂרֵה פּוֹנִים לִירוּשָׁלַיִם, לַמָּקוֹם שֶׁהַשֵּׁם בָּחַר בּוֹ. לֹא לַשֶּׁמֶשׁ וְלֹא לְמָה שֶׁנּוֹחַ – אֶלָּא לְבֵית הַמֶּלֶךְ.","פֶּרֶק י״ז, הֲלָכָה ג׳","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["בְּאֵיזֶה קוֹל אוֹמְרִים שְׁמוֹנֶה עֶשְׂרֵה?",["בְּקוֹל רָם, שֶׁכֻּלָּם יִשְׁמְעוּ","רַק בַּמַּחְשָׁבָה, בְּלִי שְׂפָתַיִם","בְּלַחַשׁ, הַשְּׂפָתַיִם זָזוֹת"],2,"כְּמוֹ חַנָּה: \"רַק שְׂפָתֶיהָ נָּעוֹת וְקוֹלָהּ לֹא יִשָּׁמֵעַ\". מַחְשָׁבָה לְבַד לֹא מַסְפִּיקָה – צָרִיךְ לְבַטֵּא אֶת הַמִּלִּים בַּשְּׂפָתַיִם, אֲבָל בְּשֶׁקֶט, שֶׁהַשָּׁכֵן לֹא יִשְׁמַע.","פֶּרֶק י״ז, הֲלָכָה ז׳","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["אֵיזוֹ עֲמִידָה מְכֻבֶּדֶת לִפְנֵי מֶלֶךְ מַלְכֵי הַמְּלָכִים?",["יָדַיִם עַל הַלֵּב, יָמִין עַל שְׂמֹאל","יָדַיִם בַּכִּיסִים","יָדַיִם עַל הַמָּתְנַיִם"],0,"אֶפְשָׁר לַעֲמֹד עִם יָדַיִם עַל הַלֵּב, אוֹ צְמוּדוֹת לַגּוּף, אוֹ עַל הַסְּטֶנְדֶּר. אֲבָל יָדַיִם בַּכִּיסִים אוֹ עַל הַמָּתְנַיִם – זוֹ לֹא עֲמִידָה שֶׁל כָּבוֹד.","פֶּרֶק י״ז, הֲלָכָה ה׳","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["אֵיךְ מִזְדַּקְּפִים אַחֲרֵי הַכְּרִיעָה?",["בִּקְפִיצָה מְהִירָה","נִשְׁאָרִים כְּפוּפִים כָּל הַתְּפִלָּה","לְאַט לְאַט"],2,"כּוֹרְעִים מַהֵר – כִּי רוֹצִים לִכְרֹעַ לִפְנֵי ה׳, וּמִזְדַּקְּפִים לְאַט – כְּמִי שֶׁהָיָה רוֹצֶה לְהַמְשִׁיךְ לִכְרֹעַ לְפָנָיו. וְהַכְּרִיעָה הִיא רַק בַּמְּקוֹמוֹת שֶׁתִּקְּנוּ חֲכָמִים.","פֶּרֶק י״ז, הֲלָכָה ו׳","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["בְּסוֹף הַתְּפִלָּה פּוֹסְעִים שָׁלֹשׁ פְּסִיעוֹת לְאָחוֹר. בְּאֵיזוֹ רֶגֶל מַתְחִילִים?",["בְּרֶגֶל יָמִין","בְּרֶגֶל שְׂמֹאל","בִּשְׁתֵּיהֶן בְּבַת אַחַת"],1,"מַתְחִילִים בְּרֶגֶל שְׂמֹאל, הַחַלָּשָׁה – כְּדֵי לְהַרְאוֹת שֶׁקָּשֶׁה לָנוּ לְהִפָּרֵד מֵהַתְּפִלָּה. וְאָז אוֹמְרִים \"עוֹשֶׂה שָׁלוֹם\".","פֶּרֶק י״ז, הֲלָכָה י״ג","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["לְמָה נִמְשְׁלָה הַתּוֹרָה, וּבִגְלַל זֶה לֹא עוֹבְרִים שְׁלֹשָׁה יָמִים בְּלִי קְרִיאָה?",["לְאֵשׁ","לְמַיִם","לְלֶחֶם"],1,"בַּמִּדְבָּר הָלְכוּ שְׁלֹשָׁה יָמִים בְּלִי מַיִם. הַתּוֹרָה הִיא כְּמוֹ מַיִם – הִיא מְחַיָּה אֶת הַנְּשָׁמָה, וְלָכֵן קוֹרְאִים בָּהּ בְּשֵׁנִי, בַּחֲמִישִׁי וּבְשַׁבָּת.","פֶּרֶק כ״ב, הֲלָכָה א׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["הַחַזָּן מוֹלִיךְ אֶת סֵפֶר הַתּוֹרָה, וְהַסֵּפֶר עוֹבֵר לְיַד מֹשֶׁה. מָה מֹשֶׁה עוֹשֶׂה?",["מְנַשֵּׁק וּמְלַוֶּה מְעַט","מַמְשִׁיךְ לְדַבֵּר עִם חָבֵר","מְדַפְדֵּף בַּסִּדּוּר"],0,"כָּל מִי שֶׁסֵּפֶר הַתּוֹרָה עוֹבֵר לְיָדוֹ מְנַשֵּׁק אוֹתוֹ וּמְלַוֶּה אוֹתוֹ כַּמָּה צְעָדִים – כָּבוֹד לַמַּתָּנָה שֶׁל ה׳.","פֶּרֶק כ״ב, הֲלָכָה ג׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["בַּעַל הַקּוֹרֵא כְּבָר קוֹרֵא מִן הַסֵּפֶר. מָה נָכוֹן לַעֲשׂוֹת?",["לְסַפֵּר לְחָבֵר בְּדִיחָה","לְדַבֵּר עִם חָבֵר עַל הֲלָכָה","לְהַקְשִׁיב בְּשֶׁקֶט"],2,"מִשֶּׁנִּפְתַּח הַסֵּפֶר אָסוּר לְדַבֵּר – אֲפִלּוּ בְּדִבְרֵי תּוֹרָה וַהֲלָכָה. מַקְשִׁיבִים לְכָל מִלָּה.","פֶּרֶק כ״ב, הֲלָכָה ח׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["בְּאֵיזֶה מֵהַיָּמִים הָאֵלֶּה לֹא אוֹמְרִים תַּחֲנוּן?",["בַּחֲנֻכָּה","בְּיוֹם חֹרֶף גָּשׁוּם","בְּיוֹם שְׁלִישִׁי רָגִיל"],0,"בַּחֲנֻכָּה שְׂמֵחִים וּמוֹדִים לַה׳ עַל הַנִּסִּים, וּבְיָמִים שֶׁל שִׂמְחָה לֹא אוֹמְרִים תַּחֲנוּן. גֶּשֶׁם אוֹ יוֹם רָגִיל אֵינָם סִבָּה לְדַלֵּג.","פֶּרֶק כ״א, הֲלָכָה ז׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["מָה עוֹשֶׂה הָעוֹלֶה לַתּוֹרָה בִּזְמַן שֶׁבַּעַל הַקּוֹרֵא קוֹרֵא?",["יוֹשֵׁב וְנָח עַל כִּסֵּא","מְדַבֵּר עִם הַגַּבַּאי","קוֹרֵא אִתּוֹ בְּלַחַשׁ"],2,"הָעוֹלֶה בֵּרֵךְ עַל הַתּוֹרָה, וְלָכֵן הוּא קוֹרֵא בְּלַחַשׁ יַחַד עִם בַּעַל הַקּוֹרֵא, מִלָּה בְּמִלָּה.","פֶּרֶק כ״ב, הֲלָכָה ו׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["מָה עוֹשִׂים בִּזְמַן הַתַּחֲנוּן שֶׁאַחֲרֵי שְׁמוֹנֶה עֶשְׂרֵה?",["נָחִים מֵהָעֲמִידָה","שׁוֹפְכִים אֶת הַלֵּב בַּעֲנָוָה","מְחַכִּים לַחַזָּן בְּשֶׁקֶט"],1,"תַּחֲנוּן הוּא תְּפִלָּה שֶׁל עֲנָוָה: אַחֲרֵי שֶׁעָמַדְנוּ לִפְנֵי ה׳, אֲנַחְנוּ מַרְגִּישִׁים שֶׁעוֹד לֹא אָמַרְנוּ הַכֹּל, וּמִתְחַנְּנִים אֵלָיו מִכָּל הַלֵּב.","פֶּרֶק כ״א, הֲלָכָה א׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["אֵיזֶה נָבִיא נַעֲנָה דַּוְקָא בִּתְפִלַּת הַמִּנְחָה?",["אֵלִיָּהוּ הַנָּבִיא","יוֹנָה הַנָּבִיא","מֹשֶׁה רַבֵּנוּ"],0,"אֵלִיָּהוּ הִתְפַּלֵּל בִּשְׁעַת הַמִּנְחָה, בַּמִּלְחָמָה שֶׁלּוֹ נֶגֶד עוֹבְדֵי הַבַּעַל – וְה׳ עָנָה לוֹ. לָכֵן נִזְהָרִים מְאוֹד בִּתְפִלַּת מִנְחָה.","פֶּרֶק כ״ד, הֲלָכָה א׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["אַבָּא שֶׁל דָּנִי עָסוּק מְאוֹד בָּעֲבוֹדָה בַּצָּהֳרַיִם. מָה הַדָּבָר הַנָּכוֹן?",["לְדַלֵּג הַיּוֹם עַל מִנְחָה","לְהִתְפַּלֵּל רַק בַּלַּיְלָה","לַעֲצֹר וּלְהִתְפַּלֵּל מִנְחָה"],2,"דַּוְקָא בְּאֶמְצַע הַיּוֹם הָעָמוּס מִתְגַּבְּרִים וְעוֹצְרִים לְמִנְחָה – וְכָךְ מְקַדְּשִׁים אֶת כָּל הָעֲבוֹדָה שֶׁל הַיּוֹם.","פֶּרֶק כ״ד, הֲלָכָה א׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["עַד מָתַי צָרִיךְ לְהִשְׁתַּדֵּל לְסַיֵּם אֶת תְּפִלַּת מִנְחָה?",["עַד חֲצוֹת הַיּוֹם","עַד שְׁקִיעַת הַחַמָּה","עַד חֲצוֹת הַלַּיְלָה"],1,"זְמַן מִנְחָה מַתְחִיל אַחֲרֵי חֲצוֹת הַיּוֹם, וּמִשְׁתַּדְּלִים לְסַיֵּם אוֹתָהּ לִפְנֵי שֶׁהַשֶּׁמֶשׁ שׁוֹקַעַת. וּבְדִיעֲבַד, לְפִי רֹב הַפּוֹסְקִים, אֶפְשָׁר לְהִתְפַּלֵּל עוֹד כְּאַרְבַּע עֶשְׂרֵה דַּקּוֹת אַחֲרֵי הַשְּׁקִיעָה.","פֶּרֶק כ״ד, הֲלָכוֹת ג׳–ד׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["מָתַי מַתְחִיל זְמַן קְרִיאַת שְׁמַע שֶׁל לַיְלָה?",["כְּשֶׁהַשֶּׁמֶשׁ זוֹרַחַת","בְּאֶמְצַע הַיּוֹם","כְּשֶׁיּוֹצְאִים הַכּוֹכָבִים"],2,"\"בְּשָׁכְבְּךָ\" – בַּזְּמַן שֶׁאֲנָשִׁים שׁוֹכְבִים לִישֹׁן. הַזְּמַן מַתְחִיל כְּשֶׁמַּחְשִׁיךְ וְרוֹאִים שְׁלֹשָׁה כּוֹכָבִים.","פֶּרֶק כ״ה, הֲלָכָה ה׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["בְּאֵיזוֹ בְּרָכָה בְּעַרְבִית מְבַקְּשִׁים שֶׁה׳ יִשְׁמֹר עָלֵינוּ בַּלַּיְלָה?",["הַשְׁכִּיבֵנוּ","מַעֲרִיב עֲרָבִים","אַהֲבַת עוֹלָם"],0,"בַּבְּרָכָה \"הַשְׁכִּיבֵנוּ\" מְבַקְּשִׁים שְׁמִירָה בַּלַּיְלָה וּבַשֵּׁנָה. \"מַעֲרִיב עֲרָבִים\" הִיא עַל חִלּוּפֵי הַזְּמַנִּים, וְ\"אַהֲבַת עוֹלָם\" – עַל אַהֲבַת ה׳ וְהַתּוֹרָה.","פֶּרֶק כ״ה, הֲלָכָה א׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["יוֹסִי כְּבָר קָרָא שְׁמַע בְּעַרְבִית. מָה יַעֲשֶׂה כְּשֶׁהוּא נִכְנָס לַמִּטָּה?",["הוֹלֵךְ יָשָׁר לִישֹׁן","קוֹרֵא שְׁמַע וּמְבָרֵךְ הַמַּפִּיל","מְשַׂחֵק עַד שֶׁנִּרְדָּם"],1,"גַּם מִי שֶׁקָּרָא שְׁמַע בְּבֵית הַכְּנֶסֶת, קוֹרֵא שׁוּב עַל הַמִּטָּה וּמְבָרֵךְ \"הַמַּפִּיל\". כָּךְ נִרְדָּמִים עִם ה׳.","פֶּרֶק כ״ו, הֲלָכָה א׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["הַחַזָּן אוֹמֵר אֶת חֲזָרַת הַשַּׁ״ץ. מָה עוֹשֶׂה דָּוִד?",["מְדַבֵּר עִם חָבֵר","לוֹמֵד גְּמָרָא","מַקְשִׁיב וְעוֹנֶה אָמֵן"],2,"בַּחֲזָרַת הַשַּׁ״ץ מַקְשִׁיבִים לַחַזָּן וְעוֹנִים אָמֵן. אָסוּר לְדַבֵּר, וַאֲפִלּוּ לִלְמֹד תּוֹרָה אָסוּר בְּאוֹתָהּ שָׁעָה.","פֶּרֶק י״ט, הֲלָכָה א׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["מָתַי עוֹנִים \"אָמֵן\" עַל בְּרָכָה שֶׁל הַחַזָּן?",["בְּאֶמְצַע הַבְּרָכָה","מִיָּד כְּשֶׁהַבְּרָכָה נִגְמֶרֶת","הַרְבֵּה זְמַן אַחַר כָּךְ"],1,"לֹא \"חוֹטְפִים\" אָמֵן לִפְנֵי סוֹף הַבְּרָכָה, וְלֹא מְאַחֲרִים עַד שֶׁהָאָמֵן נַעֲשֶׂה \"יְתוֹמָה\". עוֹנִים מִיָּד בְּסוֹף הַבְּרָכָה.","פֶּרֶק י״ט, הֲלָכָה ג׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["אוֹמְרִים קְדֻשָּׁה. אֵיךְ טוֹב לַעֲמֹד?",["רַגְלַיִם צְמוּדוֹת","יוֹשְׁבִים עַל הַסַּפְסָל","מְטַיְּלִים בֵּין הַשּׁוּרוֹת"],0,"בִּקְדֻשָּׁה טוֹב לַעֲמֹד בְּרַגְלַיִם צְמוּדוֹת, כְּמוֹ הַמַּלְאָכִים, וְנוֹהֲגִים לְהִתְרוֹמֵם מְעַט עַל קְצוֹת הָאֶצְבָּעוֹת.","פֶּרֶק י״ט, הֲלָכָה ו׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["הַחַזָּן הִגִּיעַ לְ\"מוֹדִים\". מָה עוֹשֶׂה הַקָּהָל?",["עוֹמְדִים זְקוּפִים וְשׁוֹתְקִים","כּוֹרְעִים וְאוֹמְרִים מוֹדִים דְּרַבָּנָן","יוֹשְׁבִים וּמַקְשִׁיבִים"],1,"כָּל הַקָּהָל כּוֹרֵעַ עִם הַחַזָּן וְאוֹמֵר \"מוֹדִים דְּרַבָּנָן\" – אֶת הַתּוֹדָה כָּל אֶחָד אוֹמֵר בְּעַצְמוֹ.","פֶּרֶק י״ט, הֲלָכָה ח׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["בְּיוֹם רָגִיל, בְּאֵיזוֹ תְּפִלָּה יֵשׁ בִּרְכַּת כֹּהֲנִים?",["עַרְבִית – בַּלַּיְלָה","שַׁחֲרִית – בַּבֹּקֶר","מִנְחָה – אַחֲרֵי הָאֲרוּחָה"],1,"בִּרְכַּת כֹּהֲנִים קְשׁוּרָה לַקָּרְבָּנוֹת, וְהֵם קְרֵבִים בַּיּוֹם – לָכֵן אֵין בִּרְכַּת כֹּהֲנִים בְּעַרְבִית. וּבְמִנְחָה לֹא מְבָרְכִים, שֶׁמָּא הַכֹּהֵן שָׁתָה יַיִן בָּאֲרוּחָה.","פֶּרֶק כ׳, הֲלָכָה ה׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["בִּזְמַן בִּרְכַּת כֹּהֲנִים, אֵיפֹה עוֹמְדִים?",["מֵאֲחוֹרֵי הַכֹּהֲנִים","בַּחוּץ, בַּמִּסְדְּרוֹן","מוּל הַכֹּהֲנִים"],2,"הַבְּרָכָה נֶאֱמֶרֶת פָּנִים מוּל פָּנִים. מִי שֶׁעוֹמֵד מֵאֲחוֹרֵי הַכֹּהֲנִים – אֵינוֹ בַּבְּרָכָה, וּמִי שֶׁיָּכוֹל לְהִכָּנֵס וְנִשְׁאָר בַּחוּץ – מִתְרַשֵּׁל.","פֶּרֶק כ׳, הֲלָכָה ג׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["הַכֹּהֲנִים מְבָרְכִים. לְאָן מִסְתַּכֵּל יוֹסֵף?",["מְכַוֵּן בְּלִי לְהַבִּיט","מַבִּיט בִּידֵי הַכֹּהֲנִים","מַבִּיט בַּחַלּוֹן"],0,"מְכַוְּנִים לַבְּרָכָה, וְלֹא מַבִּיטִים בַּכֹּהֲנִים וְלֹא בְּשׁוּם דָּבָר אַחֵר, כְּדֵי לֹא לְהַסִּיחַ אֶת הַדַּעַת מִן הַבְּרָכָה.","פֶּרֶק כ׳, הֲלָכָה ב׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["בְּבֵית הַכְּנֶסֶת יֵשׁ לֵוִי. מִי יוֹצֵק מַיִם עַל יְדֵי הַכֹּהֲנִים?",["הַכֹּהֵן לְבַד","לֹא נוֹטְלִים יָדַיִם","הַלֵּוִי"],2,"נוֹהֲגִים שֶׁהַלֵּוִי יוֹצֵק מַיִם עַל יְדֵי הַכֹּהֲנִים, לְהוֹסִיף קְדֻשָּׁה. רַק כְּשֶׁאֵין לֵוִי וְאֵין בְּכוֹר – הַכֹּהֵן נוֹטֵל בְּעַצְמוֹ. וּבְלִי נְטִילָה הַכֹּהֵן לֹא עוֹלֶה לַדּוּכָן.","פֶּרֶק כ׳, הֲלָכָה ו׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["אֵיךְ עוֹלִים הַכֹּהֲנִים לַדּוּכָן?",["בְּגַרְבַּיִם, בְּלִי נַעֲלַיִם","בְּנַעֲלֵי סְפּוֹרְט","בְּסַנְדָּלִים"],0,"רַבָּן יוֹחָנָן בֶּן זַכַּאי תִּקֵּן שֶׁהַכֹּהֲנִים לֹא יַעֲלוּ לַדּוּכָן בְּנַעֲלַיִם אוֹ בְּסַנְדָּלִים, מִשּׁוּם כְּבוֹד הַצִּבּוּר.","פֶּרֶק כ׳, הֲלָכָה ח׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["אַבָּא מְקַדֵּשׁ וּמוֹצִיא אוֹתְךָ יְדֵי חוֹבָה. מָה אוֹמְרִים כְּשֶׁהוּא מַזְכִּיר אֶת שֵׁם ה׳?",["בָּרוּךְ הוּא וּבָרוּךְ שְׁמוֹ","שׁוֹתְקִים וּמַקְשִׁיבִים","שָׁרִים שִׁיר שַׁבָּת"],1,"בִּבְרָכָה שֶׁיּוֹצְאִים בָּהּ יְדֵי חוֹבָה, כְּמוֹ קִדּוּשׁ, לֹא אוֹמְרִים \"בָּרוּךְ הוּא וּבָרוּךְ שְׁמוֹ\" – כְּדֵי לֹא לְהַפְסִיק בְּאֶמְצַע. שׁוֹמְעִים, וּבַסּוֹף עוֹנִים אָמֵן.","פֶּרֶק י״ט, הֲלָכָה ג׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["אֵיזוֹ תְּפִלָּה תִּקֵּן אַבְרָהָם אָבִינוּ?",["עַרְבִית – בַּלַּיְלָה","שַׁחֲרִית – בַּבֹּקֶר","מִנְחָה – אַחַר הַצָּהֳרַיִם"],1,"אַבְרָהָם אָבִינוּ הֵאִיר אֶת הָעוֹלָם בֶּאֱמוּנָתוֹ, וְלָכֵן קָבַע אֶת תְּפִלָּתוֹ כְּשֶׁהַשֶּׁמֶשׁ מַתְחִילָה לִזְרֹחַ. יִצְחָק תִּקֵּן מִנְחָה, וְיַעֲקֹב – עַרְבִית.","פֶּרֶק א׳, הֲלָכָה ז׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["בְּאֶמְצַע הַתְּפִלָּה נֹעַם שָׂם לֵב שֶׁהַמַּחֲשָׁבָה שֶׁלּוֹ בָּרְחָה. מָה יַעֲשֶׂה?",["מִתְאַמֵּץ לְכַוֵּן בְּהֶמְשֵׁךְ","סוֹגֵר אֶת הַסִּדּוּר","מַתְחִיל לְדַבֵּר"],0,"לְכֻלָּם קָשֶׁה לִפְעָמִים לְהִתְרַכֵּז. לֹא מִתְיָאֲשִׁים – מְכַוְּנִים בְּמָה שֶׁנִּשְׁאַר, וְעֶצֶם הָרָצוֹן לַעֲמֹד לִפְנֵי ה׳ הוּא כְּבָר דָּבָר עָמֹק.","פֶּרֶק א׳, הֲלָכָה ח׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["אֵיךְ עוֹנִים \"אָמֵן, יְהֵא שְׁמֵיהּ רַבָּא\" בַּקַּדִּישׁ?",["בְּלַחַשׁ","לֹא עוֹנִים","בְּקוֹל רָם"],2,"עוֹנִים בְּקוֹל רָם, וְכָל הַקָּהָל עוֹנֶה יַחַד – זֶה כְּבוֹד שָׁמַיִם. אָמְרוּ חֲכָמִים שֶׁבְּזָכוּת עֲנִיָּה כָּזוֹ מִתְבַּטְּלוֹת גְּזֵרוֹת קָשׁוֹת.","פֶּרֶק א׳, הֲלָכָה ט׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["אַבָּא שֶׁל אֵלִיָּהוּ מִתְפַּלֵּל בְּנֻסַּח עֵדָתוֹ. בְּאֵיזֶה נֻסַּח רָאוּי שֶׁיִּתְפַּלֵּל אֵלִיָּהוּ?",["בְּנֻסַּח שֶׁל הֶחָבֵר","בְּנֻסַּח אֲבוֹתָיו","בְּנֻסַּח שֶׁהוּא מַמְצִיא"],1,"רָאוּי שֶׁכָּל יְהוּדִי יַמְשִׁיךְ בְּמִנְהַג אֲבוֹתָיו, כִּי הַמְשָׁכַת הַמָּסֹרֶת חֲשׁוּבָה מְאוֹד. וְאֶת נֻסַּח הַתְּפִלָּה תִּקְּנוּ אַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה – לֹא כָּל אֶחָד מַמְצִיא לְעַצְמוֹ.","פֶּרֶק ו׳, הֲלָכָה א׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["מִי שֶׁמִּתְפַּלֵּל \"וָתִיקִין\" – מָתַי הוּא מַתְחִיל אֶת תְּפִלַּת הָעֲמִידָה?",["כְּשֶׁהַשֶּׁמֶשׁ זוֹרַחַת","בְּאֶמְצַע הַבֹּקֶר","בַּצָּהֳרַיִם"],0,"הַוָּתִיקִין קוֹרְאִים שְׁמַע מְעַט לִפְנֵי הָנֵץ הַחַמָּה, וּמַתְחִילִים אֶת הָעֲמִידָה בְּדִיּוּק עִם זְרִיחַת הַשֶּׁמֶשׁ.","פֶּרֶק י״א, הֲלָכָה ה׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["מָה מֻתָּר לַעֲשׂוֹת בַּבֹּקֶר לִפְנֵי הַתְּפִלָּה?",["לַעֲבֹד בַּחֲנוּת","לְהִסְתַּפֵּר","לְסַדֵּר אֶת הַמִּטָּה"],2,"פְּעֻלּוֹת קְטַנּוֹת, כְּמוֹ סִדּוּר הַמִּטָּה, מֻתָּרוֹת. אֲבָל עֲבוֹדָה וְתִסְפֹּרֶת אֲסוּרוֹת – קֹדֶם מִתְפַּלְּלִים.","פֶּרֶק י״ב, הֲלָכוֹת ב׳–ד׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["מָה מֻתָּר לְאַבָּא לִשְׁתּוֹת בַּבֹּקֶר לִפְנֵי שַׁחֲרִית?",["שׁוֹקוֹ מָתוֹק","כּוֹס מַיִם","מִיץ תַּפּוּזִים"],1,"מַיִם מֻתָּר לִשְׁתּוֹת, כִּי אֵין בָּהֶם שׁוּם גַּאֲוָה. אֲבָל מַשְׁקִים אֲחֵרִים אֲסוּרִים עַד אַחֲרֵי הַתְּפִלָּה.","פֶּרֶק י״ב, הֲלָכָה ו׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["אַבָּא מִתְכּוֹנֵן לִתְפִלַּת שַׁחֲרִית. מָה הַסֵּדֶר הַנָּכוֹן?",["קֹדֶם תְּפִלִּין, אַחַר כָּךְ טַלִּית","בְּלִי טַלִּית וּבְלִי תְּפִלִּין","קֹדֶם טַלִּית, אַחַר כָּךְ תְּפִלִּין"],2,"מַקְדִּימִים טַלִּית לִתְפִלִּין, כִּי הַתְּפִלִּין קְדוֹשִׁים יוֹתֵר – וְעוֹלִים בַּקְּדֻשָּׁה מִדַּרְגָּה לְדַרְגָּה.","פֶּרֶק י״ב, הֲלָכָה י׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["אַבָּא שָׁכַח אֶת הַתְּפִלִּין, וְסוֹף זְמַן קְרִיאַת שְׁמַע מִתְקָרֵב. מָה יַעֲשֶׂה?",["קוֹרֵא שְׁמַע בְּלִי תְּפִלִּין","מְחַכֶּה לַתְּפִלִּין","מְוַתֵּר עַל שְׁמַע"],0,"מִי שֶׁאֵין לוֹ תְּפִלִּין לֹא יְאַחֵר אֶת זְמַן קְרִיאַת שְׁמַע. אֵלּוּ שְׁתֵּי מִצְווֹת נִפְרָדוֹת – וְאִם אֵינוֹ יָכוֹל לְקַיֵּם אֶת שְׁתֵּיהֶן, יְקַיֵּם לְפָחוֹת אֶת הָאַחַת.","פֶּרֶק י״א, הֲלָכָה י״ב; פֶּרֶק י״ב, הֲלָכָה ט׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"]],"b":[["דָּוִד אִחֵר לְבֵית הַכְּנֶסֶת וְדִלֵּג עַל בִּרְכוֹת הַשַּׁחַר. אֵיזוֹ בְּרָכָה לֹא יוּכַל לְהַשְׁלִים אַחֲרֵי הַתְּפִלָּה?",["אֶת בִּרְכַּת \"עַל נְטִילַת יָדַיִם\" שֶׁלִּפְנֵי הַתְּפִלָּה","אֶת בִּרְכַּת \"פּוֹקֵחַ עִוְרִים\" עַל פְּקִיחַת הָעֵינַיִם","אֶת בִּרְכַּת \"שֶׁעָשָׂה לִי כָּל צָרְכִּי\" עַל הַנַּעֲלַיִם","אֶת בִּרְכַּת \"מַלְבִּישׁ עֲרֻמִּים\" עַל הַבְּגָדִים"],0,"\"עַל נְטִילַת יָדַיִם\" נִתְקְנָה כַּהֲכָנָה לַתְּפִלָּה, וְלָכֵן אַחֲרֵי הַתְּפִלָּה כְּבָר אֵין לָהּ מָקוֹם. אֶת שְׁאָר בִּרְכוֹת הַהוֹדָאָה אֶפְשָׁר לְהַשְׁלִים.","פֶּרֶק ט׳, הֲלָכָה ד׳","בֹּקֶר טוֹב לַה׳"],["רְאוּבֵן בֵּרֵךְ בִּרְכוֹת הַתּוֹרָה בַּבֹּקֶר, עָבַד כָּל הַיּוֹם, וּבָעֶרֶב בָּא לְשִׁעוּר תּוֹרָה. מָה עָלָיו לַעֲשׂוֹת?",["לְבָרֵךְ שׁוּב, כִּי הָעֲבוֹדָה הִפְסִיקָה בֵּין הַלִּמּוּדִים","לִלְמֹד בְּלִי בְּרָכָה – הַבְּרָכָה שֶׁל הַבֹּקֶר מוֹעִילָה","לְבָרֵךְ רַק אֶת הַבְּרָכָה הַשְּׁלִישִׁית \"אֲשֶׁר בָּחַר בָּנוּ\"","לִשְׁמֹעַ אֶת הַבְּרָכָה מֵהָרַב שֶׁמַּעֲבִיר אֶת הַשִּׁעוּר"],1,"בִּרְכַּת הַתּוֹרָה שֶׁל הַבֹּקֶר עוֹלָה עַל כָּל הַלִּמּוּד שֶׁל הַיּוֹם. עֲבוֹדָה, אֹכֶל וְעִסּוּקִים אֵינָם הֶפְסֵק – כִּי הַתּוֹרָה מְלַוָּה אוֹתָנוּ כָּל הַיּוֹם.","פֶּרֶק י׳, הֲלָכָה ה׳","בֹּקֶר טוֹב לַה׳"],["נֹעַם בֵּרֵךְ בִּרְכוֹת הַתּוֹרָה בַּבֹּקֶר, וְיָשַׁן שְׁעָתַיִם בַּצָּהֳרַיִם. כְּשֶׁהוּא קָם לִלְמֹד – מָה הַדִּין?",["מְבָרֵךְ שׁוּב, כִּי כָּל שֵׁנָה אֲרֻכָּה הִיא הֶפְסֵק","לֹא מְבָרֵךְ שׁוּב – נָהֲגוּ שֶׁשְּׁנַת יוֹם אֵינָהּ הֶפְסֵק","מְבָרֵךְ רַק אִם יָשַׁן עַל מִטָּה וְלֹא עַל סַפָּה","מְכַוֵּן לָצֵאת בַּבְּרָכָה שֶׁלִּפְנֵי קְרִיאַת שְׁמַע שֶׁל מִנְחָה"],1,"רַק שֵׁנַת קֶבַע בַּלַּיְלָה נֶחְשֶׁבֶת הֶפְסֵק. אֶת שְׁנַת הַיּוֹם, גַּם כְּשֶׁהִיא אֲרֻכָּה, נָהֲגוּ לְהַחְשִׁיב כְּשֵׁנַת אֲרַאי. (וּבְמִנְחָה אֵין קְרִיאַת שְׁמַע!)","פֶּרֶק י׳, הֲלָכָה ו׳","בֹּקֶר טוֹב לַה׳"],["אֵלִיָּהוּ יָשַׁן בַּלַּיְלָה עִם הַבְּגָדִים, וּבַבֹּקֶר לֹא הִתְלַבֵּשׁ. הַאִם יְבָרֵךְ \"מַלְבִּישׁ עֲרֻמִּים\"?",["לֹא, מְבָרְכִים רַק עַל מָה שֶׁנֶּהֱנֶה מִמֶּנּוּ בְּעַצְמוֹ","כֵּן, אֲבָל רַק אִם יַחֲלִיף בְּגָדִים לִפְנֵי הַתְּפִלָּה","כֵּן, הַבְּרָכוֹת נִתְקְנוּ עַל הַטּוֹבָה שֶׁל כָּל הָעוֹלָם","לֹא, אֶלָּא יִשְׁמַע אֶת הַבְּרָכָה מִן הַחַזָּן"],2,"כָּךְ פָּסַק הָרַמָּ״א, וְכָךְ נוֹהֲגִים גַּם הַסְּפָרַדִּים עַל פִּי הָאֲרִ״י: אוֹמְרִים אֶת כָּל בִּרְכוֹת הַשַּׁחַר, כִּי הֵן הוֹדָאָה עַל הַטּוֹבָה הַכְּלָלִית שֶׁהַשֵּׁם נוֹתֵן לָעוֹלָם.","פֶּרֶק ט׳, הֲלָכָה ג׳","בֹּקֶר טוֹב לַה׳"],["שִׁמְעוֹן שָׁכַח לְבָרֵךְ בִּרְכוֹת הַתּוֹרָה, וְהִגִּיעַ כְּבָר לְאֶמְצַע תְּפִלַּת שַׁחֲרִית. מָה יַעֲשֶׂה?",["יְבָרֵךְ אוֹתָן אַחֲרֵי הַתְּפִלָּה, כְּמוֹ שְׁאָר בִּרְכוֹת הַשַּׁחַר","יַפְסִיק בְּאֶמְצַע הַתְּפִלָּה וִיבָרֵךְ אוֹתָן מִיָּד","יְכַוֵּן לָצֵאת בַּבְּרָכָה שֶׁלִּפְנֵי קְרִיאַת שְׁמַע","יְכַוֵּן לָצֵאת בַּבְּרָכָה הָרִאשׁוֹנָה שֶׁל שְׁמוֹנֶה עֶשְׂרֵה"],2,"הַבְּרָכָה שֶׁלִּפְנֵי קְרִיאַת שְׁמַע (\"אַהֲבַת עוֹלָם\" / \"אַהֲבָה רַבָּה\") עוֹסֶקֶת בַּתּוֹרָה, וְיוֹצְאִים בָּהּ יְדֵי בִּרְכַּת הַתּוֹרָה. אַחֲרֵי הַתְּפִלָּה לוֹמְדִים מְעַט.","פֶּרֶק י׳, הֲלָכָה ב׳","בֹּקֶר טוֹב לַה׳"],["בִּרְכוֹת הַשַּׁחַר: הַבָּנִים מְבָרְכִים ״שֶׁלֹּא עָשַׂנִי אִשָּׁה״. מָה מְבָרְכוֹת הַבָּנוֹת בִּמְקוֹם הַבְּרָכָה הַזֹּאת?",["הֵן מְדַלְּגוֹת עַל הַבְּרָכָה, וְאֵינָן אוֹמְרוֹת דָּבָר בִּמְקוֹמָהּ","מְבָרְכוֹת ״שֶׁעָשַׂנִי כִּרְצוֹנוֹ״, כְּמוֹ שֶׁתִּקְּנוּ חֲכָמִים","מְבָרְכוֹת גַּם הֵן ״שֶׁלֹּא עָשַׂנִי אִשָּׁה״, בְּדִיּוּק כְּמוֹ הַבָּנִים","אוֹמְרוֹת ״שֶׁלֹּא עָשַׂנִי גּוֹי״ פַּעַם נוֹסֶפֶת בִּמְקוֹמָהּ"],1,"הַנָּשִׁים וְהַבָּנוֹת מְבָרְכוֹת ״שֶׁעָשַׂנִי כִּרְצוֹנוֹ״. שָׁלֹשׁ הַבְּרָכוֹת הָאֵלֶּה הֵן תּוֹדָה לַה׳ שֶׁבָּחַר בָּנוּ וְנָתַן לָנוּ אֶת מִצְווֹתָיו.","פֶּרֶק ט׳, הֲלָכָה א׳","בֹּקֶר טוֹב לַה׳"],["תָּמָר בַּת שֵׁשׁ, וּכְבָר מְבִינָה אֵיךְ נוֹטְלִים יָדַיִם. מָה עָלֶיהָ לַעֲשׂוֹת כְּשֶׁהִיא קָמָה בַּבֹּקֶר?",["כְּלוּם, כִּי נְטִילַת יָדַיִם הִיא רַק מִגִּיל שְׁתֵּים עֶשְׂרֵה","לִטֹּל יָדַיִם שָׁלֹשׁ פְּעָמִים, כְּדֵי לְהִתְרַגֵּל לַמִּצְוָה","לִשְׁטֹף פַּעַם אַחַת אֶת הַפָּנִים, וְזֶה מַסְפִּיק לִילָדִים","לְחַכּוֹת שֶׁאַבָּא יִטֹּל לָהּ אֶת הַיָּדַיִם, עַד בַּת מִצְוָה"],1,"מִצְוָה לְהַרְגִּיל אֶת הַיְּלָדִים וְהַיְּלָדוֹת מִגִּיל חִנּוּךְ לִטֹּל יָדַיִם שָׁלֹשׁ פְּעָמִים אַחֲרֵי הַשֵּׁנָה. מִגִּיל מִצְווֹת – שְׁתֵּים עֶשְׂרֵה לְבַת וּשְׁלֹשׁ עֶשְׂרֵה לְבֵן – זוֹ כְּבָר חוֹבָה.","פֶּרֶק ח׳, הֲלָכָה ח׳","בֹּקֶר טוֹב לַה׳"],["יְהוֹנָתָן קָם בַּבֹּקֶר וְלָקַח תַּפּוּחַ מֵהַקְּעָרָה לִפְנֵי שֶׁנָּטַל יָדַיִם. מָה יַעֲשֶׂה עִם הַתַּפּוּחַ?",["יִזְרֹק אוֹתוֹ לַפַּח, כִּי רוּחַ רָעָה שׁוֹרָה עָלָיו","יִשְׁטֹף אוֹתוֹ שָׁלֹשׁ פְּעָמִים בְּמַיִם, וְאָז יֹאכַל","יְנַגֵּב אוֹתוֹ הֵיטֵב בַּמַּגֶּבֶת, וְזֶה מַסְפִּיק לְגַמְרֵי","יֹאכַל אוֹתוֹ רַק אַחֲרֵי שֶׁיַּעֲבֹר יוֹם שָׁלֵם"],1,"פֵּרוֹת שֶׁנָּגְעוּ בָּהֶם לִפְנֵי הַנְּטִילָה שׁוֹטְפִים שָׁלֹשׁ פְּעָמִים – כְּמוֹ שֶׁנּוֹטְלִים כָּל יָד שָׁלֹשׁ פְּעָמִים. וּמַאֲכָל שֶׁאִי אֶפְשָׁר לִשְׁטֹף – לְפִי רֹב הַפּוֹסְקִים מֻתָּר בְּדִיעֲבַד, וְלֹא זוֹרְקִים אוֹתוֹ.","פֶּרֶק ח׳, הֲלָכָה ז׳","בֹּקֶר טוֹב לַה׳"],["אֵיתָן קָם בַּבֹּקֶר לְבַד בַּחֶדֶר, וְאַף אֶחָד לֹא רוֹאֶה אוֹתוֹ. אֵיךְ רָאוּי לוֹ לְהִתְלַבֵּשׁ?",["בִּצְנִיעוּת, כִּי ה׳ נִמְצָא בְּכָל מָקוֹם","אֵיךְ שֶׁנּוֹחַ לוֹ, כִּי אַף אֶחָד לֹא רוֹאֶה","בִּצְנִיעוּת, רַק כְּשֶׁאַחִים נִכְנָסִים לַחֶדֶר","מַהֵר מְאוֹד, כְּדֵי לְהַסְפִּיק לִפְנֵי הַתְּפִלָּה"],0,"חֲכָמִים לִמְּדוּ: אַל יֹאמַר ״מִי רוֹאֵנִי?״ – כִּי ה׳ מְלֹא כָּל הָאָרֶץ כְּבוֹדוֹ. לָכֵן מִתְלַבְּשִׁים בִּצְנִיעוּת גַּם כְּשֶׁאֲנַחְנוּ לְבַד.","פֶּרֶק ז׳, הֲלָכָה ב׳","בֹּקֶר טוֹב לַה׳"],["אַבְרָהָם הִתְעוֹרֵר בְּאֶמְצַע הַלַּיְלָה צָמֵא מְאוֹד. מָה טוֹב שֶׁיַּעֲשֶׂה לִפְנֵי שֶׁיִּשְׁתֶּה?",["יִטֹּל יָדַיִם שָׁלֹשׁ פְּעָמִים וִיבָרֵךְ ״עַל נְטִילַת יָדַיִם״","יִטֹּל יָדַיִם שָׁלֹשׁ פְּעָמִים, וְאָז יְבָרֵךְ ״שֶׁהַכֹּל״","יִשְׁתֶּה בְּלִי בְּרָכָה, כִּי עַכְשָׁו לַיְלָה וְאֵין מְבָרְכִים","יְחַכֶּה עִם הַשְּׁתִיָּה עַד שֶׁיִּתְפַּלֵּל שַׁחֲרִית בַּבֹּקֶר"],1,"בְּאֶמְצַע הַלַּיְלָה טוֹב לִטֹּל יָדַיִם שָׁלֹשׁ פְּעָמִים לִפְנֵי הַבְּרָכָה, אֲבָל לֹא מְבָרְכִים ״עַל נְטִילַת יָדַיִם״ – אֶת הַבְּרָכָה הַזֹּאת אוֹמְרִים רַק בַּבֹּקֶר. וְעַל הַמַּיִם מְבָרְכִים ״שֶׁהַכֹּל״ כָּרָגִיל.","פֶּרֶק ח׳, הֲלָכָה ו׳","בֹּקֶר טוֹב לַה׳"],["יְהוֹנָתָן קָם בַּבֹּקֶר וְהִדְלִיק שִׁירֵי קֹדֶשׁ, עוֹד לִפְנֵי שֶׁבֵּרַךְ בִּרְכוֹת הַתּוֹרָה. מָה הַדִּין?",["אָסוּר לוֹ, כִּי בַּשִּׁירִים יֵשׁ פְּסוּקִים מִן הַתּוֹרָה","מֻתָּר, רַק אִם הוּא שׁוֹמֵעַ בְּלִי לָשִׁיר בַּפֶּה","מֻתָּר, כִּי הוּא לֹא מִתְכַּוֵּן לִלְמֹד תּוֹרָה","צָרִיךְ קֹדֶם לְבָרֵךְ, כְּמוֹ לִפְנֵי לִמּוּד בַּחֻמָּשׁ"],2,"שִׁירֵי קֹדֶשׁ שֶׁשּׁוֹמְעִים בַּקִּימָה אֵינָם לִמּוּד, וְלָכֵן אֵין צֹרֶךְ לְבָרֵךְ לִפְנֵיהֶם. אֲבָל לִפְנֵי כָּל לִמּוּד – חֻמָּשׁ, מִשְׁנָה, הֲלָכָה אוֹ מִדְרָשׁ – מְבָרְכִים.","פֶּרֶק י׳, הֲלָכָה ד׳","בֹּקֶר טוֹב לַה׳"],["בְּבֵית הַכְּנֶסֶת הַקָּבוּעַ שֶׁל אֱלִיעֶזֶר לֹא הִגִּיעוּ הַיּוֹם עֲשָׂרָה. מָה עָדִיף?",["לְהִתְפַּלֵּל לְבַד בַּמָּקוֹם הַקָּבוּעַ, כִּי הַקְּבִיעוּת קוֹדֶמֶת","לָלֶכֶת לְהִתְפַּלֵּל בְּמִנְיָן בְּבֵית כְּנֶסֶת אַחֵר","לְהִתְפַּלֵּל לְבַד בְּבֵית הַכְּנֶסֶת, כִּי הוּא מִקְדָּשׁ מְעַט","לְהִתְפַּלֵּל בַּבַּיִת בְּדִיּוּק בִּשְׁעַת הַמִּנְיָן הָרָגִיל"],1,"מַעֲלַת הַמִּנְיָן גְּדוֹלָה מִמַּעֲלַת הַמָּקוֹם הַקָּבוּעַ, וְגַם מִמַּעֲלַת תְּפִלָּה לְבַד בְּבֵית הַכְּנֶסֶת. לָכֵן הוֹלְכִים לַמִּנְיָן בְּמָקוֹם אַחֵר.","פֶּרֶק ג׳, הֲלָכוֹת א׳–ב׳","בָּאִים לְבֵית ה׳"],["בְּבֵית הַכְּנֶסֶת הַקָּרוֹב לַבַּיִת רְגִילִים לְפַטְפֵּט בַּתְּפִלָּה. בְּבֵית כְּנֶסֶת רָחוֹק יוֹתֵר שׁוֹמְרִים עַל שֶׁקֶט. לְאָן כְּדַאי לָלֶכֶת?",["לַקָּרוֹב, כְּדֵי לֹא לְהִתְאַמֵּץ בַּהֲלִיכָה הָאֲרֻכָּה","אֵין הֶבְדֵּל, הָעִקָּר שֶׁיֵּשׁ שָׁם מִנְיָן שֶׁל עֲשָׂרָה","לָרָחוֹק וְהַשָּׁקֵט, כִּי שָׁם אֶפְשָׁר לְכַוֵּן יוֹתֵר","לַקָּרוֹב, כִּי חָשׁוּב לְהַגִּיעַ רִאשׁוֹן לַמִּנְיָן"],2,"בֵּית כְּנֶסֶת שֶׁשּׁוֹמְרִים בּוֹ עַל כְּבוֹד הַתְּפִלָּה עָדִיף, כִּי הָעִקָּר הַכַּוָּנָה. וְעַל כָּל צַעַד בַּדֶּרֶךְ הָאֲרֻכָּה מְקַבְּלִים שָׂכָר.","פֶּרֶק ג׳, הֲלָכָה ג׳","בָּאִים לְבֵית ה׳"],["לָמָּה תְּפִלָּה בְּמִנְיָן חֲשׁוּבָה יוֹתֵר מִתְּפִלָּה לְבַד?",["כִּי בְּמִנְיָן מִתְפַּלְּלִים יַחַד, עֲבוּר כְּלַל יִשְׂרָאֵל","כִּי רַק בְּמִנְיָן הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵעַ תְּפִלָּה","כִּי בְּמִנְיָן מִתְפַּלְּלִים מַהֵר וּמַסְפִּיקִים יוֹתֵר לִלְמֹד","כִּי לְבַד אָסוּר לְהוֹסִיף שׁוּם בַּקָּשָׁה אִישִׁית"],0,"גַּם לְבַד הַשֵּׁם שׁוֹמֵעַ, וְאַף מְשֻׁבָּח לְהוֹסִיף תְּפִלָּה אִישִׁית. אֲבָל הַמַּטָּרָה שֶׁלָּנוּ הִיא לְקַדֵּשׁ שֵׁם שָׁמַיִם יַחַד, וְלָכֵן תְּפִלַּת הַצִּבּוּר חֲשׁוּבָה יוֹתֵר.","פֶּרֶק ב׳, הֲלָכוֹת א׳–ב׳","בָּאִים לְבֵית ה׳"],["אָרִי הִגִּיעַ לְבֵית הַכְּנֶסֶת עֶשֶׂר דַּקּוֹת לִפְנֵי שַׁחֲרִית. מָה הֲכִי מַתְאִים לִלְמֹד עַכְשָׁו?",["סוּגְיָה קָשָׁה בַּגְּמָרָא, כִּי זֶה לִמּוּד חָשׁוּב בְּיוֹתֵר","שׁוּם דָּבָר, כִּי אָסוּר לִלְמֹד לִפְנֵי הַתְּפִלָּה","חִידָה מְבַדַּחַת, כְּדֵי לָבוֹא לַתְּפִלָּה בְּשִׂמְחָה","הֲלָכָה בְּרוּרָה אוֹ דִּבְרֵי אֱמוּנָה מְרוֹמָמִים"],3,"סוּגְיָה מְסֻבֶּכֶת עֲלוּלָה לְהַטְרִיד אֶת הָרֹאשׁ בַּתְּפִלָּה, וּצְחוֹק מְבַטֵּל אֶת יִרְאַת ה׳. הֲלָכָה בְּרוּרָה אוֹ דִּבְרֵי אֱמוּנָה מַכִּינִים אֶת הַלֵּב.","פֶּרֶק ה׳, הֲלָכָה א׳","בָּאִים לְבֵית ה׳"],["גִּלְעָד עָבַד בַּגִּנָּה בִּבְגָדִים מְלֻכְלָכִים, וְהַמִּנְיָן כְּבָר מַתְחִיל. מָה עָדִיף?",["לָרוּץ לַמִּנְיָן כָּךְ, כִּי מִנְיָן קוֹדֵם לַלְּבוּשׁ","לְהַחֲלִיף בְּגָדִים, גַּם אִם יַפְסִיד אֶת הַמִּנְיָן","לְהִתְפַּלֵּל בַּגִּנָּה, כְּדֵי לֹא לְלַכְלֵךְ אֶת בֵּית הַכְּנֶסֶת","לִלְבֹּשׁ מְעִיל גָּדוֹל מֵעַל הַבְּגָדִים הַמְּלֻכְלָכִים"],1,"מִי שֶׁאֵין לוֹ זְמַן לְהָבִיא כּוֹבַע וַחֲלִיפָה, יִתְפַּלֵּל בְּמִנְיָן בִּבְגָדָיו הָרְגִילִים. אֲבָל בְּגָדִים מְלֻכְלָכִים פּוֹגְעִים בִּכְבוֹד הַתְּפִלָּה, וְלָכֵן מַחֲלִיפִים.","פֶּרֶק ה׳, הֲלָכָה ד׳","בָּאִים לְבֵית ה׳"],["אָחִיו הַקָּטָן שֶׁל אֶלְחָנָן בֶּן שָׁנָה וָחֵצִי, וְאַבָּא שׁוֹאֵל אִם לָקַחַת אוֹתוֹ לִתְפִלַּת שַׁחֲרִית. מָה נָכוֹן?",["לָקַחַת אוֹתוֹ, כְּדֵי שֶׁיִּסְפֹּג קְדֻשָּׁה בִּזְמַן הַתְּפִלָּה","לֹא לָקַחַת, כִּי תִּינוֹק עָלוּל לְהַפְרִיעַ לַמִּתְפַּלְּלִים","לָקַחַת אוֹתוֹ, וּלְהוֹשִׁיב אוֹתוֹ מִמּוּל בִּזְמַן שְׁמוֹנֶה עֶשְׂרֵה","לֹא לָקַחַת אַף פַּעַם, עַד שֶׁיַּגִּיעַ לְגִיל בַּר מִצְוָה"],1,"תִּינוֹקוֹת וִילָדִים שֶׁעוֹד לֹא יוֹדְעִים לְהִתְפַּלֵּל מַפְרִיעִים לַכַּוָּנָה, וְלָכֵן לֹא מְבִיאִים אוֹתָם בִּזְמַן הַתְּפִלָּה. אֲבָל מִגִּיל חִנּוּךְ – אַדְּרַבָּה, מְבִיאִים אֶת הַיֶּלֶד, וּמְלַמְּדִים אוֹתוֹ לָשֶׁבֶת בְּיִרְאָה וְלַעֲנוֹת אָמֵן.","פֶּרֶק ה׳, הֲלָכָה ו׳","בָּאִים לְבֵית ה׳"],["בְּבֵית הַכְּנֶסֶת יֵשׁ תִּשְׁעָה גְּבָרִים, וְגַם אֲבִיחַי בֶּן אַחַת עֶשְׂרֵה. מִישֶׁהוּ מַצִּיעַ לָתֵת לוֹ חֻמָּשׁ בַּיָּד וּלְצָרֵף אוֹתוֹ. מָה הַדִּין?",["מְצָרְפִים אוֹתוֹ, כִּי הַחֻמָּשׁ בְּיָדוֹ הוֹפֵךְ אוֹתוֹ לְגָדוֹל","לְפִי רֹב הַפּוֹסְקִים לֹא מְצָרְפִים אוֹתוֹ, וְכָךְ הַמִּנְהָג","מְצָרְפִים אוֹתוֹ, אִם הוּא יוֹדֵעַ לְהִתְפַּלֵּל בְּעַל פֶּה","מְצָרְפִים אוֹתוֹ לְקַדִּישׁ, אֲבָל לֹא לַחֲזָרַת הַשַּׁ״ץ"],1,"מִנְיָן הוּא עֲשָׂרָה גְּבָרִים מִגִּיל בַּר מִצְוָה. יֵשׁ מֵהָרִאשׁוֹנִים שֶׁהִתִּירוּ בִּשְׁעַת הַדְּחָק לְצָרֵף יֶלֶד שֶׁמַּחֲזִיק חֻמָּשׁ, אֲבָל לְדַעַת רֹב הַפּוֹסְקִים אֵין מְצָרְפִים אוֹתוֹ, וְכָךְ הַמִּנְהָג.","פֶּרֶק ב׳, הֲלָכָה ו׳","בָּאִים לְבֵית ה׳"],["יוֹסִי רוֹצֶה לִרְאוֹת אֶת הַחַזָּן טוֹב יוֹתֵר, וְחוֹשֵׁב לַעֲמֹד עַל כִּסֵּא בִּזְמַן הַתְּפִלָּה. מָה נָכוֹן?",["אָסוּר, כִּי עוֹמְדִים לִפְנֵי ה׳ בַּעֲנָוָה","מֻתָּר, כִּי כָּךְ הוּא יְכַוֵּן טוֹב יוֹתֵר עִם הַחַזָּן","מֻתָּר, אִם הוּא מַחֲזִיק חָזָק בַּשֻּׁלְחָן שֶׁלְּפָנָיו","אָסוּר רַק מִפְּנֵי הַסַּכָּנָה שֶׁיִּפֹּל מֵהַכִּסֵּא"],0,"חֲכָמִים אָמְרוּ: לֹא יַעֲמֹד אָדָם עַל כִּסֵּא אוֹ עַל מָקוֹם גָּבוֹהַּ וְיִתְפַּלֵּל, כִּי אֵין גַּאֲוָה לִפְנֵי ה׳ – ״מִמַּעֲמַקִּים קְרָאתִיךָ ה׳״.","פֶּרֶק ג׳, הֲלָכָה ד׳","בָּאִים לְבֵית ה׳"],["עוֹזֵר נִכְנַס לְבֵית הַכְּנֶסֶת. יֵשׁ מָקוֹם פָּנוּי לְיַד הַחַלּוֹן שֶׁפּוֹנֶה לָרְחוֹב, וְיֵשׁ מָקוֹם בִּפְנִים. מָה עָדִיף?",["לְיַד הַחַלּוֹן, כְּדֵי שֶׁיִּהְיֶה לוֹ אוֹר טוֹב לַסִּדּוּר","לְיַד הַפֶּתַח, כְּדֵי לָצֵאת מַהֵר אַחֲרֵי הַתְּפִלָּה","בִּפְנִים, כְּדֵי שֶׁלֹּא יַבִּיט הַחוּצָה בַּתְּפִלָּה","אֵין הֶבְדֵּל, הָעִקָּר שֶׁהוּא בְּתוֹךְ בֵּית הַכְּנֶסֶת"],2,"לֹא יוֹשְׁבִים לְיַד חַלּוֹן אוֹ פֶּתַח שֶׁפּוֹנִים הַחוּצָה, כְּדֵי שֶׁהָעֵינַיִם לֹא יִבְרְחוּ לָרְחוֹב. וְגַם לְיַד הַפֶּתַח לֹא עוֹמְדִים – כְּאִלּוּ מְמַהֲרִים לָצֵאת.","פֶּרֶק ג׳, הֲלָכָה ה׳","בָּאִים לְבֵית ה׳"],["בִּתְפִלַּת עַרְבִית יֵשׁ מוּל מְקוֹמוֹ שֶׁל יָאִיר חַלּוֹן, וּבַחֹשֶׁךְ הוּא רוֹאֶה בּוֹ אֶת הַבָּבוּאָה שֶׁלּוֹ. מָה נָכוֹן?",["אָסוּר לְהִתְפַּלֵּל שָׁם בְּשׁוּם אֹפֶן, כְּמוֹ מוּל מַרְאָה","יִסְתַּכֵּל בַּסִּדּוּר אוֹ יַעֲצֹם עֵינַיִם, וְאָז מֻתָּר","אֵין שׁוּם בְּעָיָה, כִּי חַלּוֹן אֵינוֹ מַרְאָה","יַדְלִיק אֶת כָּל הָאוֹרוֹת, כְּדֵי לִרְאוֹת אֶת הַבָּבוּאָה טוֹב"],1,"חַלּוֹן לֹא מַרְאֶה אֶת הַבָּבוּאָה בְּבֵרוּר כְּמוֹ מַרְאָה, וְלָכֵן מִי שֶׁמִּסְתַּכֵּל בַּסִּדּוּר אוֹ עוֹצֵם עֵינַיִם – מֻתָּר לוֹ. אֲבָל לְכַתְּחִלָּה לֹא מִתְפַּלְּלִים מוּלוֹ, וְטוֹב לִתְלוֹת וִילוֹנוֹת וּלְכַסּוֹת אֶת הַחַלּוֹנוֹת לִפְנֵי עַרְבִית.","פֶּרֶק ג׳, הֲלָכָה ו׳","בָּאִים לְבֵית ה׳"],["בֵּית הַכְּנֶסֶת תָּפוּס עַל יְדֵי מִנְיָן אַחֵר, וּבְצַלְאֵל מִתְפַּלֵּל בַּחוּץ. אֵיפֹה אָסוּר לוֹ לַעֲמֹד, וְלָמָּה?",["מֵאֲחוֹרֵי בֵּית הַכְּנֶסֶת, כִּי שָׁם הוּא רָחוֹק מִן הָאָרוֹן","בְּצַד בֵּית הַכְּנֶסֶת, כִּי שָׁם לֹא שׁוֹמְעִים אֶת הַחַזָּן","בֵּין בֵּית הַכְּנֶסֶת לִירוּשָׁלַיִם, כִּי גַּבּוֹ יִפְנֶה לְאֶחָד מֵהֶם","בְּשׁוּם מָקוֹם בַּחוּץ, כִּי מִתְפַּלְּלִים רַק בְּתוֹךְ בַּיִת"],2,"אִם יַעֲמֹד בֵּין בֵּית הַכְּנֶסֶת לִירוּשָׁלַיִם: כְּשֶׁיִּפְנֶה לִירוּשָׁלַיִם – גַּבּוֹ לְבֵית הַכְּנֶסֶת, וּכְשֶׁיִּפְנֶה לְבֵית הַכְּנֶסֶת – גַּבּוֹ לִירוּשָׁלַיִם. מֵאֲחוֹרֵי בֵּית הַכְּנֶסֶת אוֹ בְּצִדּוֹ מֻתָּר, כְּשֶׁפָּנָיו לִירוּשָׁלַיִם.","פֶּרֶק ג׳, הֲלָכָה ח׳","בָּאִים לְבֵית ה׳"],["אֶסְתֵּר מִתְפַּלֶּלֶת שַׁחֲרִית בַּבַּיִת, וְהִיא יוֹדַעַת שֶׁבְּבֵית הַכְּנֶסֶת שֶׁבַּשְּׁכוּנָה מִתְפַּלְּלִים בְּשָׁעָה שְׁמוֹנֶה. מָתַי כְּדַאי לָהּ לְהִתְפַּלֵּל?",["בְּאוֹתָהּ שָׁעָה שֶׁהַצִּבּוּר מִתְפַּלֵּל, כִּי זוֹ עֵת רָצוֹן","מֻקְדָּם כְּכָל הָאֶפְשָׁר, עוֹד לִפְנֵי שֶׁהַצִּבּוּר מַתְחִיל","אַחֲרֵי שֶׁהַצִּבּוּר גּוֹמֵר, כְּדֵי שֶׁלֹּא יַפְרִיעוּ לָהּ","אֵין הֶבְדֵּל, כִּי בַּבַּיִת מִתְפַּלְּלִים בְּכָל שָׁעָה"],0,"מִי שֶׁמִּתְפַּלֵּל בַּבַּיִת מְכַוֵּן אֶת תְּפִלָּתוֹ לַשָּׁעָה שֶׁהַצִּבּוּר מִתְפַּלֵּל, וְכָךְ מִשְׁתַּתֵּף קְצָת בִּתְפִלָּתָם. וְאִם אֵינוֹ יוֹדֵעַ מָתַי מִתְפַּלְּלִים – בְּכָל שָׁעָה יֵשׁ בָּעוֹלָם מִנְיָן שֶׁעוֹמֵד בִּתְפִלָּה.","פֶּרֶק ב׳, הֲלָכָה ג׳","בָּאִים לְבֵית ה׳"],["אֵלִיָּהוּ חוֹלֶה וְשׁוֹכֵב בַּמִּטָּה, וּמֵהַחַלּוֹן הוּא שׁוֹמֵעַ אֶת הַחַזָּן בְּבֵית הַכְּנֶסֶת הַסָּמוּךְ אוֹמֵר קַדִּישׁ. מָה הַדִּין?",["לֹא יַעֲנֶה בִּכְלָל, כִּי הוּא לֹא נִמְצָא עִם הָעֲשָׂרָה","יַעֲנֶה אָמֵן, כִּי שׁוּם קִיר לֹא מַפְרִיד מִן הַשְּׁכִינָה","יַעֲנֶה רַק אִם הוּא רוֹאֶה אֶת הַחַזָּן מֵהַחַלּוֹן","יַעֲנֶה רַק אִם יָקוּם וְיִתְלַבֵּשׁ בִּבְגָדִים מְכֻבָּדִים"],1,"כְּשֶׁיֵּשׁ מִנְיָן בְּבֵית הַכְּנֶסֶת, כָּל מִי שֶׁשּׁוֹמֵעַ אֶת הַחַזָּן יָכוֹל לַעֲנוֹת אַחֲרָיו אָמֵן – אֲפִלּוּ מְחִצָּה שֶׁל בַּרְזֶל לֹא מַפְסִיקָה. וּמִי שֶׁשּׁוֹמֵעַ חַזָּן בְּשִׁדּוּר חַי – עוֹנֶה אָמֵן, אֲבָל אֵינוֹ יוֹצֵא בְּכָךְ יְדֵי חוֹבַת תְּפִלָּה.","פֶּרֶק ב׳, הֲלָכָה ט׳","בָּאִים לְבֵית ה׳"],["צִיצִית הִיא מִצְוָה שֶׁל יוֹם. אִם כָּךְ, לָמָּה קוֹרְאִים אֶת פָּרָשַׁת \"וַיֹּאמֶר\" גַּם בַּלַּיְלָה?",["כִּי בְּסוֹפָהּ מַזְכִּירִים אֶת יְצִיאַת מִצְרַיִם","כִּי בַּלַּיְלָה לוֹבְשִׁים טַלִּית קָטָן גַּם בַּשֵּׁנָה","כְּדֵי שֶׁלֹּא לְשַׁנּוֹת אֶת הַסֵּדֶר שֶׁל הַבֹּקֶר","כִּי בָּהּ מְקַבְּלִים עֹל מַלְכוּת שָׁמַיִם"],0,"מִצְוָה לִזְכֹּר אֶת יְצִיאַת מִצְרַיִם בַּיּוֹם וּבַלַּיְלָה, וּפָרָשַׁת \"וַיֹּאמֶר\" מִסְתַּיֶּמֶת בָּהּ. עֹל מַלְכוּת שָׁמַיִם – בַּפָּרָשָׁה הָרִאשׁוֹנָה.","פֶּרֶק ט״ו, הֲלָכָה ב׳","שָׁרִים וּמַמְלִיכִים"],["לָמָּה פָּרָשַׁת \"שְׁמַע\" בָּאָה לִפְנֵי פָּרָשַׁת \"וְהָיָה אִם שָׁמֹעַ\"?",["כִּי הִיא קְצָרָה יוֹתֵר וְקַל לְהַתְחִיל בָּהּ","כִּי בָּהּ כְּתוּבָה מִצְוַת הַצִּיצִית שֶׁל הַיּוֹם","כְּדֵי לְקַבֵּל עֹל מַלְכוּת שָׁמַיִם לִפְנֵי עֹל מִצְווֹת","כִּי הִיא מְדַבֶּרֶת עַל הַשָּׂכָר וְהָעֹנֶשׁ שֶׁל כָּל הַמִּצְווֹת"],2,"קֹדֶם מְקַבְּלִים אֶת ה׳ כְּמֶלֶךְ, וְאַחַר כָּךְ אֶת מִצְווֹתָיו. שָׂכָר וָעֹנֶשׁ – בְּ\"וְהָיָה אִם שָׁמֹעַ\", וְצִיצִית – בְּ\"וַיֹּאמֶר\".","פֶּרֶק ט״ו, הֲלָכָה א׳","שָׁרִים וּמַמְלִיכִים"],["אִיתַי הִגִּיעַ מְאֻחָר, וְהַצִּבּוּר כִּמְעַט מְסַיֵּם פְּסוּקֵי דְּזִמְרָה. מָה יַעֲשֶׂה?",["יֹאמַר אֶת כָּל פְּסוּקֵי דְּזִמְרָה, גַּם אִם יַפְסִיד אֶת הַמִּנְיָן","יֹאמַר \"בָּרוּךְ שֶׁאָמַר\", \"אַשְׁרֵי\" וְ\"יִשְׁתַּבַּח\", וִידַלֵּג עַל הַשְּׁאָר","יְדַלֵּג עַל הַכֹּל וְיַתְחִיל מִיָּד בִּשְׁמוֹנֶה עֶשְׂרֵה","יְדַלֵּג עַל \"אַשְׁרֵי\" וְיַשְׁלִים אוֹתוֹ אַחֲרֵי הַתְּפִלָּה"],1,"תְּפִלָּה בְּמִנְיָן חֲשׁוּבָה יוֹתֵר מִשְּׁאָר הַפְּרָקִים, אֲבָל אֶת בִּרְכוֹת פְּסוּקֵי דְּזִמְרָה אִי אֶפְשָׁר לְהַשְׁלִים אַחַר כָּךְ, וּבִשְׁבִילָן צָרִיךְ לְפָחוֹת פֶּרֶק אֶחָד – \"אַשְׁרֵי\".","פֶּרֶק י״ד, הֲלָכָה ה׳","שָׁרִים וּמַמְלִיכִים"],["לָמָּה אָסוּר לְהַפְסִיק בֵּין \"גָּאַל יִשְׂרָאֵל\" לִשְׁמוֹנֶה עֶשְׂרֵה?",["כְּדֵי לְהַסְפִּיק לְהִתְפַּלֵּל שְׁמוֹנֶה עֶשְׂרֵה יַחַד עִם כָּל הַצִּבּוּר","כִּי זְמַן שְׁמוֹנֶה עֶשְׂרֵה עָלוּל לַעֲבֹר בֵּינְתַיִם","כִּי כָּךְ לֹא נִשְׁכַּח אֶת נֹסַח הַבְּרָכוֹת","כִּי זֶה כְּמוֹ לִדְפֹּק לַמֶּלֶךְ וְלָלֶכֶת כְּשֶׁהוּא פּוֹתֵחַ"],3,"הַזְכָּרַת יְצִיאַת מִצְרַיִם הִיא כְּמוֹ דְּפִיקָה עַל דֶּלֶת הַמֶּלֶךְ. וְזֶה אֲפִלּוּ חָשׁוּב יוֹתֵר מִתְּפִלָּה עִם הַצִּבּוּר – מִי שֶׁמְּאַחֵר מִתְפַּלֵּל כַּסֵּדֶר וְסוֹמֵךְ גְּאֻלָּה לִתְפִלָּה.","פֶּרֶק ט״ז, הֲלָכָה ז׳","שָׁרִים וּמַמְלִיכִים"],["לָמָּה בַּבְּרָכָה \"יוֹצֵר אוֹר\" מַזְכִּירִים שֶׁה׳ בָּרָא גַּם אֶת הַחֹשֶׁךְ?",["כִּי אוֹמְרִים אוֹתָהּ גַּם בַּלַּיְלָה, בִּזְמַן תְּפִלַּת עַרְבִית","כְּדֵי לְהַדְגִּישׁ שֶׁה׳ אֶחָד, וְהוּא בָּרָא אֶת הַכֹּל","כְּדֵי לְהוֹדוֹת עַל הַשֵּׁנָה הַטּוֹבָה שֶׁל הַלַּיְלָה","כִּי הַתְּפִלָּה מַתְחִילָה לִפְנֵי שֶׁהַשֶּׁמֶשׁ זוֹרַחַת"],1,"גַּם הָאוֹר וְגַם הַחֹשֶׁךְ בָּאִים מֵה׳ הָאֶחָד – וְאֵין עוֹד מִלְּבַדּוֹ. בַּלַּיְלָה אוֹמְרִים בְּרָכָה אַחֶרֶת: \"הַמַּעֲרִיב עֲרָבִים\".","פֶּרֶק ט״ז, הֲלָכָה א׳","שָׁרִים וּמַמְלִיכִים"],["אֵיךְ מְלַמֶּדֶת אוֹתָנוּ פָּרָשַׁת שְׁמַע לֹא לִשְׁכֹּחַ אֶת הָאֱמוּנָה בַּה׳?",["קוֹרְאִים אוֹתָהּ בַּבֹּקֶר וּבָעֶרֶב, וְגַם בִּתְפִלִּין וּבִמְזוּזָה","לוֹמְדִים אוֹתָהּ פַּעַם אַחַת הֵיטֵב, וְזֶה מַסְפִּיק","אוֹמְרִים אוֹתָהּ רַק בְּשַׁבָּתוֹת וּבְחַגִּים בְּבֵית הַכְּנֶסֶת","כּוֹתְבִים אוֹתָהּ פַּעַם בְּשָׁנָה בְּמַחְבֶּרֶת מְיֻחֶדֶת"],0,"גַּם מִי שֶׁלָּמַד הֵיטֵב עָלוּל לִשְׁכֹּחַ בְּתוֹךְ טִרְדוֹת הַיּוֹם. לָכֵן הַתּוֹרָה צִוְּתָה לִקְרֹא שְׁמַע בַּבֹּקֶר וּבָעֶרֶב, לְהַנִּיחַ אֶת הַפָּרָשָׁה בַּתְּפִלִּין וְלִקְבֹּעַ אוֹתָהּ בַּמְּזוּזָה.","פֶּרֶק ט״ו, הֲלָכָה ג׳","שָׁרִים וּמַמְלִיכִים"],["מְנַחֵם קוֹרֵא אֶת פָּרָשַׁת ״וַיֹּאמֶר״ וּמַגִּיעַ לַמִּלִּים ״וּרְאִיתֶם אֹתוֹ״. מָה נוֹהֲגִים לַעֲשׂוֹת בָּרֶגַע הַזֶּה?",["לְהִסְתַּכֵּל בַּצִּיצִיּוֹת שֶׁהוּא אוֹחֵז בְּיָדוֹ","לִנְגֹּעַ בַּתְּפִלִּין שֶׁל רֹאשׁ וּלְנַשֵּׁק אֶת הַיָּד","לְכַסּוֹת אֶת הָעֵינַיִם בְּיַד יָמִין, כְּמוֹ בִּ״שְׁמַע״","לַעֲמֹד וְלִכְרֹעַ, כִּי זֶה פָּסוּק חָשׁוּב בִּמְיֻחָד"],0,"כְּשֶׁאוֹמְרִים ״וּרְאִיתֶם אֹתוֹ״ מִסְתַּכְּלִים בַּצִּיצִיּוֹת, וְיֵשׁ נוֹהֲגִים לְהַעֲבִירָן עַל הָעֵינַיִם וּלְנַשְּׁקָן. אֶת הַתְּפִלִּין מְמַשְׁמְשִׁים בְּ״וּקְשַׁרְתָּם״ וּבְ״וְהָיוּ לְטֹטָפֹת״.","פֶּרֶק ט״ו, הֲלָכָה י״א","שָׁרִים וּמַמְלִיכִים"],["אַרְיֵה אִחֵר, וְהוּא בְּאֶמְצַע בִּרְכוֹת קְרִיאַת שְׁמַע כְּשֶׁהַחַזָּן מַגִּיעַ לִקְדֻשָּׁה. מָה יַעֲשֶׂה?",["יַמְשִׁיךְ בַּבְּרָכָה, כִּי אָסוּר לְהַפְסִיק בִּבְרָכוֹת קְרִיאַת שְׁמַע","יַפְסִיק וְיֹאמַר אֶת כָּל הַקְּדֻשָּׁה, יַחַד עִם הַחַזָּן","יַפְסִיק וְיַעֲנֶה ״קָדוֹשׁ״ וּ״בָרוּךְ״, וְיַמְשִׁיךְ בַּבְּרָכָה","יַעֲנֶה עַל הַקְּדֻשָּׁה, וְאַחַר כָּךְ יַחְזֹר לִתְחִלַּת הַבְּרָכָה"],2,"לִשְׁבָחִים הַגְּדוֹלִים שֶׁל הַצִּבּוּר מֻתָּר לְהַפְסִיק גַּם בְּאֶמְצַע בִּרְכוֹת קְרִיאַת שְׁמַע. אֲבָל עוֹנִים רַק אֶת הָעִקָּר – ״קָדוֹשׁ״ וּ״בָרוּךְ״ (וְנוֹהֲגִים גַּם ״יִמְלֹךְ״), וּמַמְשִׁיכִים מֵהַמָּקוֹם שֶׁעָצְרוּ.","פֶּרֶק ט״ז, הֲלָכָה ה׳","שָׁרִים וּמַמְלִיכִים"],["בְּאֶמְצַע בִּרְכוֹת קְרִיאַת שְׁמַע רוֹאֶה גִּדְעוֹן שֶׁאָחִיו הַקָּטָן עוֹמֵד לֶאֱכֹל סֻכָּרִיָּה בְּלִי בְּרָכָה. מָה יַעֲשֶׂה?",["לֹא יַעֲשֶׂה כְּלוּם, כִּי אָסוּר לְהַפְסִיק בַּתְּפִלָּה","יְרַמֵּז לוֹ, וְאִם לֹא יָבִין יֹאמַר לוֹ בַּפֶּה","יְחַכֶּה עַד אַחֲרֵי הַתְּפִלָּה, וְאָז יַסְבִּיר לוֹ","יֹאמַר לוֹ אֶת הַבְּרָכָה בְּקוֹל, כְּדֵי שֶׁיַּעֲנֶה אַחֲרָיו"],1,"הָרוֹאֶה חָבֵר שֶׁעוֹמֵד לַעֲשׂוֹת אִסּוּר – רוֹמֵז לוֹ קֹדֶם. וְאִם הוּא לֹא מֵבִין – מֻתָּר לְהַפְסִיק בְּדִבּוּר כְּדֵי לְהַצִּיל אוֹתוֹ מִן הָאִסּוּר.","פֶּרֶק ט״ז, הֲלָכָה ו׳","שָׁרִים וּמַמְלִיכִים"],["אָבִיו שֶׁל נָתָן חוֹלֶה, וְנָתָן רוֹצֶה לְבַקֵּשׁ עָלָיו בִּשְׁמוֹנֶה עֶשְׂרֵה. בְּאֵיזוֹ בְּרָכָה כְּדַאי לוֹ לְהוֹסִיף אֶת הַבַּקָּשָׁה?",["בַּבְּרָכָה הָרִאשׁוֹנָה, כְּדֵי שֶׁהַבַּקָּשָׁה תִּהְיֶה רִאשׁוֹנָה","בִּבְרָכַת ״רְפָאֵנוּ״, שֶׁהִיא הַבְּרָכָה עַל הָרְפוּאָה","בְּבִרְכַּת ״מוֹדִים״, כִּי בָּהּ כּוֹרְעִים לִפְנֵי הַמֶּלֶךְ","בַּבְּרָכָה הָאַחֲרוֹנָה שֶׁל הַתְּפִלָּה, עַל הַשָּׁלוֹם"],1,"בַּקָּשָׁה פְּרָטִית מוֹסִיפִים בַּבְּרָכוֹת הָאֶמְצָעִיּוֹת, בַּבְּרָכָה שֶׁמַּתְאִימָה לָהּ – עַל חוֹלֶה בִּ״רְפָאֵנוּ״ (וְאֶפְשָׁר גַּם בְּ״שׁוֹמֵעַ תְּפִלָּה״). בְּשָׁלֹשׁ הָרִאשׁוֹנוֹת מְשַׁבְּחִים וּבְשָׁלֹשׁ הָאַחֲרוֹנוֹת מוֹדִים – שָׁם לֹא מְבַקְּשִׁים בַּקָּשׁוֹת פְּרָטִיּוֹת.","פֶּרֶק י״ז, הֲלָכָה י״א","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["אַהֲרֹן הִגִּיעַ לְסוֹף בִּרְכַּת ״אָבוֹת״ וְהֵבִין שֶׁלֹּא כִּוֵּן בָּהּ בִּכְלָל. עוֹד לֹא אָמַר אֶת שֵׁם ה׳ בַּחֲתִימָה. מָה יַעֲשֶׂה?",["יַמְשִׁיךְ הָלְאָה, וִיכַוֵּן הֵיטֵב בְּבִרְכַּת ״מוֹדִים״","יַחֲזֹר לְ״אֱלֹהֵי אַבְרָהָם״ וְיֹאמַר שׁוּב בְּכַוָּנָה","יְסַיֵּם אֶת כָּל הַתְּפִלָּה, וְיִתְפַּלֵּל שׁוּב מֵהַהַתְחָלָה","יַחֲזֹר לְ״ה׳ שְׂפָתַי תִּפְתָּח״ שֶׁלִּפְנֵי הַתְּפִלָּה"],1,"כָּל עוֹד לֹא אָמַר אֶת שֵׁם ה׳ בַּחֲתִימָה, אֶפְשָׁר לְתַקֵּן: חוֹזְרִים לְ״אֱלֹהֵי אַבְרָהָם״ וּמְכַוְּנִים. לְהַתְחִיל שׁוּב אֶת כָּל הַתְּפִלָּה – הַיּוֹם לֹא עוֹשִׂים, כִּי יֵשׁ חֲשָׁשׁ שֶׁגַּם בַּפַּעַם הַשְּׁנִיָּה לֹא יְכַוֵּן.","פֶּרֶק י״ז, הֲלָכָה ט׳","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["יְהוֹנָתָן עוֹמֵד בְּאֶמְצַע שְׁמוֹנֶה עֶשְׂרֵה, וְשׁוֹמֵעַ אֶת הַחַזָּן מַתְחִיל קְדֻשָּׁה. מָה יַעֲשֶׂה?",["יַעֲנֶה ״קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ״ בְּקוֹל יַחַד עִם הַצִּבּוּר","יִשְׁתֹּק וִיכַוֵּן לַחַזָּן, וְזֶה נֶחְשָׁב כְּאִלּוּ עָנָה","יַעֲנֶה, וְאַחַר כָּךְ יַחֲזֹר לִתְחִלַּת הַבְּרָכָה שֶׁלּוֹ","יִרְמֹז לַחַזָּן לְהַמְתִּין עַד שֶׁיְּסַיֵּם אֶת תְּפִלָּתוֹ"],1,"בְּאֶמְצַע שְׁמוֹנֶה עֶשְׂרֵה לֹא עוֹנִים, אֲפִלּוּ לִקְדֻשָּׁה. אֲבָל אֶפְשָׁר לִשְׁתֹּק וּלְכַוֵּן לְמָה שֶׁהַחַזָּן אוֹמֵר – וְזֶה נֶחְשָׁב כְּאִלּוּ אָמַר בְּעַצְמוֹ. וְאִם הַשְּׁתִיקָה מַפְרִיעָה לוֹ לְכַוֵּן – עָדִיף שֶׁיַּמְשִׁיךְ לְהִתְפַּלֵּל.","פֶּרֶק י״ז, הֲלָכָה ט״ו","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["אִיתַי אִחֵר לְבֵית הַכְּנֶסֶת. הַמָּקוֹם הַקָּבוּעַ שֶׁלּוֹ נִמְצָא מֵעֵבֶר לְאִישׁ שֶׁעוֹמֵד בִּשְׁמוֹנֶה עֶשְׂרֵה. מָה יַעֲשֶׂה?",["יַעֲבֹר מַהֵר, כִּי מָקוֹם קָבוּעַ הוּא מִצְוָה חֲשׁוּבָה","יַעֲבֹר לְאַט וּבְשֶׁקֶט, כְּדֵי שֶׁלֹּא יַפְרִיעַ לוֹ","יִתְפַּלֵּל בְּמָקוֹם אַחֵר, בְּלִי לַעֲבֹר לְפָנָיו","יְבַקֵּשׁ מִמֶּנּוּ בִּתְנוּעַת יָד שֶׁיָּזוּז מְעַט"],2,"אָסוּר לַעֲבֹר לִפְנֵי הַמִּתְפַּלֵּל בְּתוֹךְ אַרְבַּע אַמּוֹת, וְגַם הַמָּקוֹם הַקָּבוּעַ אֵינוֹ סִבָּה לְהַתִּיר. גַּם בְּשֶׁקֶט – הָעוֹבֵר עָלוּל לְהַסִּיחַ אֶת דַּעְתּוֹ שֶׁל הַמִּתְפַּלֵּל, שֶׁעוֹמֵד לִפְנֵי הַשְּׁכִינָה.","פֶּרֶק י״ז, הֲלָכוֹת י״ח–י״ט","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["שְׁלֹמֹה שָׁכַח ״יַעֲלֶה וְיָבוֹא״ בְּשַׁחֲרִית שֶׁל רֹאשׁ חֹדֶשׁ, וּבַחֲנֻכָּה שָׁכַח ״עַל הַנִּסִּים״. בִּשְׁנֵי הַמִּקְרִים נִזְכַּר רַק אַחֲרֵי הַתְּפִלָּה. מָה הַדִּין?",["בְּרֹאשׁ חֹדֶשׁ חוֹזֵר וּמִתְפַּלֵּל, וּבַחֲנֻכָּה אֵינוֹ חוֹזֵר","בִּשְׁנֵיהֶם חוֹזֵר, כִּי שְׁתֵּי הַתּוֹסָפוֹת חֲשׁוּבוֹת מְאֹד","בִּשְׁנֵיהֶם אֵינוֹ חוֹזֵר, כִּי אֵלֶּה רַק תּוֹסָפוֹת","בַּחֲנֻכָּה חוֹזֵר בִּגְלַל הַנֵּס, וּבְרֹאשׁ חֹדֶשׁ אֵינוֹ חוֹזֵר"],0,"מִי שֶׁשָּׁכַח ״יַעֲלֶה וְיָבוֹא״ בְּשַׁחֲרִית אוֹ בְּמִנְחָה שֶׁל רֹאשׁ חֹדֶשׁ – חוֹזֵר וּמִתְפַּלֵּל. אֲבָל חֲנֻכָּה וּפוּרִים הֵם מִדִּבְרֵי חֲכָמִים, וְלָכֵן מִי שֶׁשָּׁכַח ״עַל הַנִּסִּים״ אֵינוֹ חוֹזֵר.","פֶּרֶק י״ח, הֲלָכָה ב׳","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["הַיּוֹם שְׁמִינִי עֲצֶרֶת, וְהִתְחַלְנוּ לוֹמַר ״מַשִּׁיב הָרוּחַ וּמוֹרִיד הַגֶּשֶׁם״. מָתַי נַתְחִיל לְבַקֵּשׁ ״וְתֵן טַל וּמָטָר״?",["כְּבָר הַיּוֹם בְּמוּסָף, יַחַד עִם הַשֶּׁבַח עַל הַגֶּשֶׁם","בְּלֵיל ז׳ בְּמַרְחֶשְׁוָן, כְּדֵי שֶׁעוֹלֵי הָרֶגֶל יַגִּיעוּ הַבַּיְתָה","בְּרֹאשׁ חֹדֶשׁ כִּסְלֵו, כְּשֶׁמַּתְחִילִים הַגְּשָׁמִים הַגְּדוֹלִים שֶׁל הַחֹרֶף","רַק אַחֲרֵי שֶׁיֵּרֵד בָּאָרֶץ הַגֶּשֶׁם הָרִאשׁוֹן שֶׁל הַשָּׁנָה"],1,"אֶת שֶׁבַח הַגֶּשֶׁם מַתְחִילִים בְּמוּסָף שֶׁל שְׁמִינִי עֲצֶרֶת, אֲבָל אֶת הַבַּקָּשָׁה דָּחוּ בַּחֲמִשָּׁה עָשָׂר יוֹם – לְלֵיל ז׳ בְּמַרְחֶשְׁוָן, כְּדֵי שֶׁעוֹלֵי הָרֶגֶל שֶׁבָּאוּ מִנְּהַר פְּרָת יַסְפִּיקוּ לַחֲזֹר בְּלִי שֶׁיֵּרֵד עֲלֵיהֶם גֶּשֶׁם.","פֶּרֶק י״ח, הֲלָכָה ד׳","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["אָחִיו הַקָּטָן שֶׁל אֶלְיָשִׁיב, בֶּן שֶׁבַע, עוֹמֵד בִּשְׁמוֹנֶה עֶשְׂרֵה בְּאֶמְצַע הַמַּעֲבָר. אֶלְיָשִׁיב צָרִיךְ לַעֲבֹר לְפָנָיו. מָה הַדִּין?",["אָסוּר לְגַמְרֵי, בְּדִיּוּק כְּמוֹ לִפְנֵי גָּדוֹל, לְכָל הַדֵּעוֹת","הֲלָכָה כַּמְּקִלִּים, וְהַמְהַדְּרִים נִזְהָרִים שֶׁלֹּא לַעֲבֹר","מֻתָּר רַק אִם יְבַקֵּשׁ מִמֶּנּוּ רְשׁוּת לִפְנֵי הַתְּפִלָּה","מֻתָּר, כִּי תְּפִלָּה שֶׁל יֶלֶד אֵינָהּ נֶחְשֶׁבֶת תְּפִלָּה"],1,"נֶחְלְקוּ הָאַחֲרוֹנִים אִם דִּין יֶלֶד שֶׁמִּתְפַּלֵּל כְּדִין גָּדוֹל. כֵּיוָן שֶׁהָאִסּוּר לַעֲבֹר לִפְנֵי הַמִּתְפַּלֵּל הוּא מִדִּבְרֵי חֲכָמִים – הֲלָכָה כַּמְּקִלִּים, וְהַמְהַדְּרִים מַחְמִירִים. וּתְפִלַּת הַיֶּלֶד חֲשׁוּבָה מְאוֹד: הוּא מִתְחַנֵּךְ לַעֲמֹד לִפְנֵי ה׳.","פֶּרֶק י״ז, הֲלָכָה כ״א","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["מָתַי פּוֹסְעִים שָׁלֹשׁ פְּסִיעוֹת קָדִימָה בִּתְפִלַּת שַׁחֲרִית?",["לִפְנֵי סִיּוּם ״גָּאַל יִשְׂרָאֵל״, כְּדֵי לְהַתְחִיל מִיָּד עֲמִידָה","אַחֲרֵי הַבְּרָכָה הָרִאשׁוֹנָה שֶׁל תְּפִלַּת הָעֲמִידָה","בִּזְמַן שֶׁהַחַזָּן אוֹמֵר אֶת הַקַּדִּישׁ הָאַחֲרוֹן","בְּסוֹף הַתְּפִלָּה, כְּשֶׁאוֹמְרִים ״עוֹשֶׂה שָׁלוֹם״"],0,"פּוֹסְעִים קָדִימָה כְּדֵי לְהִתְקָרֵב לַעֲמֹד לִפְנֵי ה׳. עוֹשִׂים זֹאת לִפְנֵי שֶׁמְּסַיְּמִים ״גָּאַל יִשְׂרָאֵל״, כְּדֵי שֶׁלֹּא לְהַפְסִיק בֵּין הַגְּאֻלָּה לַתְּפִלָּה.","פֶּרֶק י״ז, הֲלָכָה ב׳","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["נֹעַם כְּבָר גָּמַר לְהִתְפַּלֵּל, וְהָאִישׁ שֶׁלְּיָדוֹ עוֹד עוֹמֵד בָּעֲמִידָה. נֹעַם רוֹצֶה לָשֶׁבֶת לְיָדוֹ וְלַחְכּוֹת. מָה נָכוֹן?",["נִשְׁאָר לַעֲמֹד, אוֹ יוֹשֵׁב וְאוֹמֵר ״אַשְׁרֵי״ וְ״עָלֵינוּ״","יוֹשֵׁב וְנָח, כִּי הוּא כְּבָר סִיֵּם אֶת הַתְּפִלָּה","יוֹשֵׁב רַק אִם הוּא שׁוֹתֵק וְלֹא מַפְרִיעַ","יוֹצֵא מִבֵּית הַכְּנֶסֶת עַד שֶׁכֻּלָּם יְסַיְּמוּ"],0,"אָסוּר לָשֶׁבֶת סְתָם בְּתוֹךְ אַרְבַּע אַמּוֹת שֶׁל הַמִּתְפַּלֵּל, כִּי זֶה נִרְאֶה כְּזִלְזוּל בַּתְּפִלָּה. מִי שֶׁעָסוּק בַּתְּפִלָּה – מֻתָּר לוֹ לָשֶׁבֶת.","פֶּרֶק י״ז, הֲלָכָה י״ז","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["לְעִידוֹ יֵשׁ נַזֶּלֶת, וְהַצִּבּוּר עוֹמֵד לְהַתְחִיל שְׁמוֹנֶה עֶשְׂרֵה. מָה נָכוֹן לַעֲשׂוֹת?",["לְקַנֵּחַ אֶת הָאַף עַכְשָׁו, לִפְנֵי שֶׁמַּתְחִילִים לְהִתְפַּלֵּל","לְהַתְחִיל לְהִתְפַּלֵּל, וּלְקַנֵּחַ רַק כְּשֶׁיִּגְמֹר אֶת כָּל הַתְּפִלָּה","לֹא לְהִתְפַּלֵּל בִּכְלָל הַיּוֹם, עַד שֶׁיַּבְרִיא מִן הַנַּזֶּלֶת","לְהִתְפַּלֵּל בִּמְהִירוּת, כְּדֵי שֶׁהַנַּזֶּלֶת לֹא תַּפְרִיעַ לוֹ"],0,"לִפְנֵי הָעֲמִידָה מְסִירִים כָּל מַה שֶּׁעָלוּל לְהַפְרִיעַ, כְּמוֹ נַזֶּלֶת. וְאִם צָרִיךְ לְקַנֵּחַ בְּאֶמְצַע הַתְּפִלָּה – עוֹשִׂים זֹאת בַּצּוּרָה הַמְּנֻמֶּסֶת בְּיוֹתֵר, וּמִי שֶׁמְּפַהֵק – מַנִּיחַ יָד עַל הַפֶּה.","פֶּרֶק י״ז, הֲלָכָה ב׳","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["שָׁאוּל סִיֵּם אֶת הָעֲמִידָה וּפָסַע שָׁלֹשׁ פְּסִיעוֹת לְאָחוֹר. מָתַי יַחֲזֹר לִמְקוֹמוֹ?",["מִיָּד, כִּי הוּא כְּבָר גָּמַר אֶת כָּל הַתְּפִלָּה","רַק בְּסוֹף הַתְּפִלָּה כֻּלָּהּ, אַחֲרֵי ״עָלֵינוּ לְשַׁבֵּחַ״","כְּשֶׁהַחַזָּן מַגִּיעַ לִקְדֻשָּׁה, אוֹ לְפָחוֹת מַתְחִיל אֶת הַחֲזָרָה","אַחֲרֵי שֶׁיַּחֲזֹר עוֹד שָׁלֹשׁ פְּסִיעוֹת לְאָחוֹר"],2,"לֹא חוֹזְרִים מִיָּד לַמָּקוֹם. לְכַתְּחִלָּה מְחַכִּים בַּמָּקוֹם שֶׁבּוֹ נִגְמְרוּ הַפְּסִיעוֹת עַד שֶׁהַחַזָּן מַגִּיעַ לִקְדֻשָּׁה, וּלְפָחוֹת עַד שֶׁהוּא מַתְחִיל אֶת חֲזָרַת הַשַּׁ״ץ. גַּם מִי שֶׁמִּתְפַּלֵּל לְבַד מְחַכֶּה כַּחֲצִי דַּקָּה.","פֶּרֶק י״ז, הֲלָכָה י״ד","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["נְתַנְאֵל גָּמַר אֶת הָעֲמִידָה, וּמִיָּד מֵאֲחוֹרָיו, קָרוֹב מְאוֹד, עוֹמֵד אִישׁ שֶׁעוֹד מִתְפַּלֵּל. מָה יַעֲשֶׂה?",["יִפְסַע מַהֵר לְאָחוֹר, לִפְנֵי שֶׁהָאִישׁ יַרְגִּישׁ בּוֹ","יְחַכֶּה עַד שֶׁהָאִישׁ יְסַיֵּם, וְאָז יִפְסַע לְאָחוֹר","יִפְסַע קָדִימָה שָׁלֹשׁ פְּסִיעוֹת בִּמְקוֹם לְאָחוֹר","יְוַתֵּר עַל הַפְּסִיעוֹת וְיֵשֵׁב מִיָּד בִּמְקוֹמוֹ"],1,"לֹא פּוֹסְעִים לְתוֹךְ אַרְבַּע הָאַמּוֹת שֶׁל מִי שֶׁעוֹמֵד בִּתְפִלָּה, גַּם אִם הוּא מַאֲרִיךְ. בֵּינְתַיִם מֻתָּר לַעֲנוֹת אָמֵן וּ״בָרוּךְ הוּא וּבָרוּךְ שְׁמוֹ״ וּלְהַמְשִׁיךְ בַּתְּפִלּוֹת, וּכְשֶׁהוּא מְסַיֵּם – פּוֹסְעִים וְאוֹמְרִים ״עוֹשֶׂה שָׁלוֹם״.","פֶּרֶק י״ז, הֲלָכָה כ׳","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["הַיּוֹם ז׳ בְּחֶשְׁוָן, וּמַתְחִילִים לְבַקֵּשׁ ״וְתֵן טַל וּמָטָר״. מָה כְּדַאי לְאוּרִי לַעֲשׂוֹת כְּדֵי שֶׁלֹּא יִטְעֶה?",["לְהִתְפַּלֵּל לְאַט מְאוֹד, בְּלִי לַחֲזֹר עַל הַנֻּסָּח","לַחֲזֹר תִּשְׁעִים פַּעַם עַל הַנֻּסָּח הֶחָדָשׁ שֶׁל הַבְּרָכָה","לְדַלֵּג עַל בִּרְכַּת הַשָּׁנִים עַד שֶׁיִּתְרַגֵּל לַנֻּסָּח","לוֹמַר אֶת שְׁנֵי הַנֻּסָּחִים, הַיָּשָׁן וְהֶחָדָשׁ, בְּכָל תְּפִלָּה"],1,"בַּיּוֹם שֶׁמַּחֲלִיפִים אֶת הַנֻּסָּח טוֹב לַחֲזֹר עָלָיו תִּשְׁעִים פַּעַם, עַד שֶׁיִּהְיֶה שָׁגוּר עַל הַלָּשׁוֹן. כָּךְ לֹא טוֹעִים – וְגַם אִם מִסְתַּפְּקִים אַחַר כָּךְ, מִן הַסְּתָם אָמַרְנוּ נָכוֹן.","פֶּרֶק י״ח, הֲלָכָה ו׳","עוֹמְדִים לִפְנֵי הַמֶּלֶךְ"],["נָתָן מְצֻנָּן וּמִשְׁתַּעֵל, וְסֵפֶר הַתּוֹרָה עוֹבֵר לְיָדוֹ. מָה כְּדַאי לוֹ לַעֲשׂוֹת?",["יְנַשֵּׁק אֶת הַסֵּפֶר בְּפִיו, כִּי זֶה הַמִּנְהָג שֶׁל רֹב הַצִּבּוּר","יִגַּע בַּסֵּפֶר בְּיָדוֹ, וְאַחַר כָּךְ יְנַשֵּׁק אֶת יָדוֹ","יַעֲמֹד בִּמְקוֹמוֹ וְלֹא יִתְקָרֵב, כִּי חוֹלֶה פָּטוּר מִכְּבוֹד הַתּוֹרָה","יְנַשֵּׁק בְּפִיו אֶת הַמְּעִיל, כִּי הַמְּעִיל אֵינוֹ חֵלֶק מֵהַסֵּפֶר"],1,"חוֹלֶה לֹא יְנַשֵּׁק בְּפִיו, כְּדֵי שֶׁלֹּא יַדְבִּיק אֶת הַמִּתְפַּלְּלִים. נְגִיעָה בַּיָּד וּנְשִׁיקַת הַיָּד הִיא גַּם דֶּרֶךְ שֶׁל כָּבוֹד – וְיֵשׁ שֶׁנּוֹהֲגִים כָּךְ תָּמִיד.","פֶּרֶק כ״ב, הֲלָכָה ג׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["בַּעַל הַקּוֹרֵא קוֹרֵא בְּקוֹל בִּשְׁבִיל הָעוֹלֶה. לָמָּה הָעוֹלֶה צָרִיךְ בְּכָל זֹאת לִקְרֹא אִתּוֹ בְּלַחַשׁ?",["כְּדֵי לְהִתְאַמֵּן, כִּי בַּפַּעַם הַבָּאָה יִקְרָא לְבַד","כְּדֵי שֶׁיּוּכַל לְתַקֵּן מִיָּד אֶת הַקּוֹרֵא כְּשֶׁהוּא טוֹעֶה","כְּדֵי שֶׁהַצִּבּוּר יִשְׁמַע שְׁנֵי קוֹלוֹת וְיָבִין טוֹב יוֹתֵר אֶת הַפְּסוּקִים","כִּי הוּא בֵּרֵךְ, וּבְלִי קְרִיאָתוֹ הַבְּרָכָה עֲלוּלָה לִהְיוֹת לְבַטָּלָה"],3,"הָעוֹלֶה הוּא שֶׁמְּבָרֵךְ עַל הַקְּרִיאָה, וְלָכֵן עָלָיו לִקְרֹא גַּם בְּעַצְמוֹ, בְּלַחַשׁ, מִלָּה בְּמִלָּה. בַּעַל הַקּוֹרֵא קוֹרֵא בְּקוֹל כְּדֵי שֶׁלֹּא יִתְבַּיֵּשׁ מִי שֶׁאֵינוֹ יוֹדֵעַ לִקְרֹא.","פֶּרֶק כ״ב, הֲלָכוֹת ה׳–ו׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["הַמַּגְבִּיהַּ הֵרִים אֶת סֵפֶר הַתּוֹרָה הַפָּתוּחַ. מָה כְּדַאי לוֹ לַעֲשׂוֹת עַכְשָׁו?",["לְהִסְתּוֹבֵב לְאַט סִבּוּב שָׁלֵם, שֶׁכֻּלָּם יִרְאוּ אֶת הַכְּתָב","לִפְנוֹת מְעַט יָמִינָה וּמְעַט שְׂמֹאלָה, וּמִיָּד לָשֶׁבֶת עִם הַסֵּפֶר","לְהַגְבִּיהַּ אֶת הַסֵּפֶר כְּשֶׁהוּא סָגוּר, כְּדֵי שֶׁלֹּא יִפֹּל מִיָּדָיו","לַעֲמֹד בְּשֶׁקֶט מוּל אֲרוֹן הַקֹּדֶשׁ, כִּי מִשָּׁם רוֹאִים הֲכִי טוֹב"],0,"מַגְבִּיהִים כְּדֵי לְהַרְאוֹת אֶת אוֹתִיּוֹת הַתּוֹרָה לְכָל הַקָּהָל. מִי שֶׁפּוֹנֶה רַק מְעַט לַצְּדָדִים – רַבִּים לֹא רוֹאִים. סִבּוּב שָׁלֵם וְאִטִּי מַרְאֶה לְכֻלָּם.","פֶּרֶק כ״ב, הֲלָכָה ד׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["עֲזַרְיָה מֻכְרָח לָצֵאת לִפְנֵי סוֹף שַׁחֲרִית. עַד אֵיזֶה מָקוֹם כְּדַאי לוֹ לְהִשָּׁאֵר לְפָחוֹת?",["עַד אַחֲרֵי הַתַּחֲנוּן, כִּי הוּא הַחֵלֶק הֶחָשׁוּב בְּיוֹתֵר שֶׁל הַסִּיּוּם","מֻתָּר לוֹ לָצֵאת מִיָּד בְּסוֹף חֲזָרַת הַשַּׁ״ץ","עַד אַחֲרֵי קְדֻשָּׁה דְּסִדְרָא, שֶׁנֶּאֱמֶרֶת בְּתוֹךְ וּבָא לְצִיּוֹן","עַד אַחֲרֵי אַשְׁרֵי, כִּי אַחֲרָיו כְּבָר אֵין דָּבָר חָשׁוּב"],2,"תַּחֲנוּן הוּא רְשׁוּת, וְאִלּוּ עַל קְדֻשָּׁה דְּסִדְרָא אָמְרוּ חֲכָמִים שֶׁבִּזְכוּתָהּ הָעוֹלָם עוֹמֵד. לָכֵן הַמְּמַהֵר נִשְׁאָר לְפָחוֹת עַד אַחֲרֶיהָ, וְלֹא מֵסִיר תְּפִלִּין לִפְנֵי כֵן.","פֶּרֶק כ״ג, הֲלָכָה ג׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["בַּקַּדִּישׁ עוֹנִים \"אָמֵן, יְהֵא שְׁמֵהּ רַבָּא\". לָמָּה כְּדַאי לַעֲצֹר רֶגַע קָטָן אַחֲרֵי הַמִּלָּה \"אָמֵן\"?",["כְּדֵי לִנְשֹׁם אֲוִיר וְלוֹמַר אֶת הַמִּלִּים בְּקוֹל רָם יוֹתֵר","כִּי אָמֵן עוֹנֶה עַל דִּבְרֵי הַחַזָּן, וְהַשְּׁאָר הוּא שֶׁבַח חָדָשׁ","כְּדֵי לְחַכּוֹת שֶׁכָּל הַצִּבּוּר יַגִּיעַ וְיַעֲנֶה יַחַד בְּקוֹל אֶחָד","כִּי אָסוּר לוֹמַר שְׁתֵּי תְּשׁוּבוֹת לַחַזָּן בְּלִי הַפְסָקָה בֵּינֵיהֶן כְּלָל"],1,"\"אָמֵן\" עוֹנֶה עַל מָה שֶׁאָמַר הַחַזָּן לִפְנֵי כֵן, וְ\"יְהֵא שְׁמֵהּ רַבָּא\" הוּא שֶׁבַח בִּפְנֵי עַצְמוֹ – וְאוֹמְרִים אוֹתוֹ בְּכָל הַכַּוָּנָה.","פֶּרֶק כ״ג, הֲלָכָה י״א","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["בִּזְמַן הַהַגְבָּהָה הַבָּנוֹת שֶׁבְּעֶזְרַת הַנָּשִׁים רוֹאוֹת אֶת כְּתַב הַתּוֹרָה. מָה מִצְוָה לוֹמַר?",["״וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל״","״שְׁמַע יִשְׂרָאֵל ה׳ אֱלֹהֵינוּ ה׳ אֶחָד״, כְּמוֹ בִּקְרִיאַת שְׁמַע","שׁוּם דָּבָר, כִּי הַמִּצְוָה הַזֹּאת הִיא רַק לַגְּבָרִים","״אָמֵן, יְהֵא שְׁמֵהּ רַבָּא״, כְּמוֹ שֶׁעוֹנִים בַּקַּדִּישׁ"],0,"מִצְוָה עַל כָּל הָאֲנָשִׁים וְהַנָּשִׁים שֶׁרוֹאִים אֶת הַכְּתָב לִכְרֹעַ וְלוֹמַר ״וְזֹאת הַתּוֹרָה״. רַבִּים מֵהָאַשְׁכְּנַזִּים לֹא נָהֲגוּ לִכְרֹעַ, וְיֵשׁ שֶׁלִּמְּדוּ עַל כָּךְ זְכוּת.","פֶּרֶק כ״ב, הֲלָכָה ד׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["שִׁמְעוֹן מִתְפַּלֵּל שַׁחֲרִית לְבַד בַּבַּיִת, וְהִגִּיעַ לִשְׁלֹשׁ עֶשְׂרֵה הַמִּדּוֹת. מָה יַעֲשֶׂה?",["יְדַלֵּג, אוֹ יֹאמַר אוֹתָן בְּטַעֲמֵי הַמִּקְרָא","יֹאמַר אוֹתָן כָּרָגִיל, כִּי הֵן בַּקָּשָׁה חֲשׁוּבָה","יֹאמַר אוֹתָן פַּעֲמַיִם, כְּדֵי לְהַשְׁלִים אֶת הַמִּנְיָן","יַפְסִיק אֶת הַתְּפִלָּה וְיֵלֵךְ לְחַפֵּשׂ מִנְיָן"],0,"שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הֵן דָּבָר שֶׁבִּקְדֻשָּׁה, וְאוֹמְרִים אוֹתָן רַק בַּעֲשָׂרָה. הַמִּתְפַּלֵּל לְבַד יָכוֹל לִקְרֹא אוֹתָן בְּטַעֲמֵי הַמִּקְרָא, כְּמוֹ קוֹרֵא בַּתּוֹרָה.","פֶּרֶק כ״א, הֲלָכָה ה׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["לָמָּה לִפְנֵי שִׁיר שֶׁל יוֹם אוֹמְרִים ״הַיּוֹם יוֹם שֵׁנִי בְּשַׁבָּת״?",["כְּדֵי לִזְכֹּר אֶת יוֹם הַשַּׁבָּת בְּכָל יְמֵי הַשָּׁבוּעַ","כְּדֵי שֶׁהַמִּתְפַּלְּלִים יֵדְעוּ אֵיזֶה עַמּוּד לִפְתֹּחַ","כִּי בְּיוֹם שֵׁנִי לֹא אוֹמְרִים אֶת שִׁיר הַשַּׁבָּת","כְּדֵי לְהַזְכִּיר שֶׁהַלְוִיִּם שָׁרוּ רַק בַּשַּׁבָּת"],0,"סוֹפְרִים אֶת הַיָּמִים ״רִאשׁוֹן בְּשַׁבָּת, שֵׁנִי בְּשַׁבָּת...״ – וְכָךְ מְקַיְּמִים בְּכָל יוֹם אֶת הַמִּצְוָה ״זָכוֹר אֶת יוֹם הַשַּׁבָּת״. אֶת הַשִּׁיר עַצְמוֹ שָׁרוּ הַלְוִיִּם בְּבֵית הַמִּקְדָּשׁ.","פֶּרֶק כ״ג, הֲלָכָה ד׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["בְּסוֹף שַׁחֲרִית אוֹמֵר הַצִּבּוּר ״עָלֵינוּ לְשַׁבֵּחַ״. אֵיךְ נוֹהֲגִים לוֹמַר אוֹתָהּ?",["בִּישִׁיבָה, כִּי זוֹ תְּפִלָּה שֶׁאַחֲרֵי סוֹף הַתְּפִלָּה","בַּעֲמִידָה, וְכוֹרְעִים מְעַט בַּמִּלִּים ״וַאֲנַחְנוּ כּוֹרְעִים״","בַּעֲמִידָה, וְנוֹפְלִים עַל הַפָּנִים כְּמוֹ בַּתַּחֲנוּן","כָּל אֶחָד כִּרְצוֹנוֹ, כִּי אֵין בָּהּ שׁוּם מִנְהָג"],1,"מִפְּנֵי חֲשִׁיבוּתָהּ אוֹמְרִים ״עָלֵינוּ לְשַׁבֵּחַ״ בַּעֲמִידָה, וְכוֹרְעִים מְעַט בְּ״וַאֲנַחְנוּ כּוֹרְעִים״. וְגַם מִי שֶׁנֻּסָּחוֹ שׁוֹנֶה – לֹא יוֹשֵׁב כְּשֶׁכָּל הַצִּבּוּר עוֹמֵד.","פֶּרֶק כ״ג, הֲלָכָה ה׳","תַּחֲנוּן, תּוֹרָה וְקַדִּישׁ"],["מִשְׁפַּחַת לֵוִי מְתַכְנֶנֶת סְעוּדַת בְּרִית גְּדוֹלָה אַחֲרֵי חֲצוֹת הַיּוֹם, וְעוֹד לֹא הִתְפַּלְּלוּ מִנְחָה. מָה עָדִיף?",["אוֹכְלִים בְּלִי דְּאָגָה, כִּי זְמַן מִנְחָה נִמְשָׁךְ עַד הַלַּיְלָה","מְדַלְּגִים הַיּוֹם עַל מִנְחָה, כִּי סְעוּדַת מִצְוָה פּוֹטֶרֶת מִתְּפִלָּה","קֹדֶם מִתְפַּלְּלִים מִנְחָה, כִּי בִּסְעוּדָה גְּדוֹלָה קַל לִשְׁכֹּחַ","מִתְפַּלְּלִים מִנְחָה רַק אִם הַסְּעוּדָה תִּמָּשֵׁךְ אַחֲרֵי הַשְּׁקִיעָה"],2,"סְעוּדָה רַבַּת מִשְׁתַּתְּפִים עֲלוּלָה לְהִמָּשֵׁךְ וּלְהַשְׁכִּיחַ אֶת הַתְּפִלָּה, וְלָכֵן לֹא מַתְחִילִים אוֹתָהּ לִפְנֵי מִנְחָה. רַק בִּשְׁעַת הַדְּחָק מַתְחִילִים קֹדֶם – כְּשֶׁבָּרוּר שֶׁיַּסְפִּיקוּ לְסַיֵּם בַּזְּמַן, וְדוֹאֲגִים לְהַזְכִּיר לְהִתְפַּלֵּל.","פֶּרֶק כ״ד, הֲלָכָה ו׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["בְּשַׁחֲרִית וּבְמִנְחָה הַחַזָּן חוֹזֵר עַל הַתְּפִלָּה בְּקוֹל. לָמָּה בְּעַרְבִית אֵין חֲזָרַת הַשַּׁ״ץ?",["כִּי מִתְּחִלָּה עַרְבִית הָיְתָה רְשׁוּת, וְלֹא תִּקְּנוּ לָהּ חֲזָרָה","כִּי בַּלַּיְלָה כֻּלָּם עֲיֵפִים, וְרוֹצִים לְסַיֵּם מַהֵר אֶת הַתְּפִלָּה","כִּי בְּעַרְבִית אוֹמְרִים קַדִּישׁ בֵּין קְרִיאַת שְׁמַע לַעֲמִידָה","כִּי עַרְבִית נִתְקְנָה כְּנֶגֶד קָרְבַּן הַתָּמִיד שֶׁל בֵּין הָעַרְבַּיִם"],0,"עַרְבִית נִתְקְנָה כְּנֶגֶד הַקְטָרַת חֶלְקֵי הַקָּרְבָּנוֹת בַּלַּיְלָה, שֶׁאֵינָהּ מְעַכֶּבֶת – וְלָכֵן הָיְתָה רְשׁוּת. אַף שֶׁקִּבַּלְנוּ אוֹתָהּ כְּחוֹבָה, לֹא תִּקְּנוּ לָהּ חֲזָרַת הַשַּׁ״ץ. (כְּנֶגֶד הַתָּמִיד שֶׁל בֵּין הָעַרְבַּיִם – זוֹ מִנְחָה!)","פֶּרֶק כ״ה, הֲלָכָה ב׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["חֲצִי שָׁעָה לִפְנֵי צֵאת הַכּוֹכָבִים מֵאִיר רָעֵב מְאוֹד, וְעוֹד לֹא קָרָא שְׁמַע וְלֹא הִתְפַּלֵּל עַרְבִית. מָה מֻתָּר לוֹ?",["לְהַתְחִיל אֲרוּחָה קַלָּה, כִּי רַק סְעוּדָה גְּדוֹלָה אֲסוּרָה","שׁוּם דָּבָר, אֲפִלּוּ לֹא תַּפּוּחַ אוֹ מְלָפְפוֹן קָטָן","לִשְׁכַּב לִישֹׁן מְעַט, כְּדֵי שֶׁיִּתְפַּלֵּל עַרְבִית בְּכֹחַ","לֶאֱכֹל פֵּרוֹת וִירָקוֹת, אֲבָל לֹא לְהַתְחִיל אֲרוּחָה"],3,"לִפְנֵי עַרְבִית אָסוּר לְהַתְחִיל אֲפִלּוּ אֲרוּחָה קַלָּה, וְגַם לֹא לִישֹׁן – שֶׁמָּא יֵרָדֵם וְיַפְסִיד אֶת קְרִיאַת שְׁמַע. פֵּרוֹת וִירָקוֹת אֵינָם אֲרוּחָה, וְהֵם מֻתָּרִים.","פֶּרֶק כ״ה, הֲלָכָה ט׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["אֲבִיעַד בֵּרֵךְ \"הַמַּפִּיל\", אֲבָל שָׁכַב עֵר זְמַן רַב וְלֹא נִרְדַּם. מָה דִּין הַבְּרָכָה שֶׁלּוֹ?",["הִיא לְבַטָּלָה, וְלָכֵן עָלָיו לוֹמַר בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ","אֵינָהּ לְבַטָּלָה, כִּי הִיא הוֹדָאָה לַה׳ עַל הַשֵּׁנָה","עָלָיו לְבָרֵךְ שׁוּב רֶגַע לִפְנֵי שֶׁיֵּרָדֵם בֶּאֱמֶת","הַבְּרָכָה תְּלוּיָה בְּכַמָּה זְמַן יִישַׁן בְּסוֹפוֹ שֶׁל דָּבָר"],1,"\"הַמַּפִּיל\" הִיא בִּרְכַּת שֶׁבַח וְהוֹדָאָה לַה׳ עַל הַשֵּׁנָה, וְהוֹדָאָה אֵינָהּ לְבַטָּלָה. וּמְבָרְכִים אוֹתָהּ רַק פַּעַם אַחַת בַּלַּיְלָה – לֹא חוֹזְרִים עָלֶיהָ.","פֶּרֶק כ״ו, הֲלָכָה ב׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["לִפְנֵי הַשֵּׁנָה נִזְכַּר יְהוּדָה שֶׁחָבֵר הֶעֱלִיב אוֹתוֹ הַיּוֹם. מָה כְּדַאי לוֹ לַעֲשׂוֹת?",["לְחַכּוֹת לְמָחָר, וְרַק אִם יְבַקֵּשׁ סְלִיחָה לִמְחֹל לוֹ","לִכְתֹּב אֶת זֶה בְּמַחְבֶּרֶת, כְּדֵי לֹא לִשְׁכֹּחַ מָה קָרָה","לַחְשֹׁב אֵיךְ לְהַחְזִיר לוֹ מָחָר עַל הָעֶלְבּוֹן","לִמְחֹל לוֹ בַּלֵּב, כְּדֵי שֶׁלֹּא יֵעָנֵשׁ חֲבֵרוֹ בִּגְלָלוֹ"],3,"בַּעֲלֵי הַמּוּסָר לִמְּדוּ: לִפְנֵי הַשֵּׁנָה מוֹחֲלִים לְכָל מִי שֶׁפָּגַע בָּנוּ, כְּדֵי שֶׁאַף אֶחָד לֹא יֵעָנֵשׁ בִּגְלָלֵנוּ – וּבִזְכוּת זֶה מַאֲרִיכִים יָמִים.","פֶּרֶק כ״ו, הֲלָכָה ג׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["מִשְׁפַּחַת לֵוִי חוֹזֶרֶת מִטִּיּוּל בַּלַּיְלָה. אַבָּא וְהַבָּנִים הוֹלְכִים לְעַרְבִית. מָה דִּין הַבָּנוֹת?",["פְּטוּרוֹת מֵעַרְבִית, כִּי הִיא הָיְתָה מִתְּחִלָּה רְשׁוּת","חַיָּבוֹת בְּעַרְבִית, בְּדִיּוּק כְּמוֹ הַגְּבָרִים וְהַבָּנִים","חַיָּבוֹת בְּעַרְבִית, אֲבָל רַק בְּמוֹצָאֵי שַׁבָּת וְחַג","פְּטוּרוֹת מִכָּל תְּפִלָּה, וְאֵין לָהֶן שׁוּם חִיּוּב לְהִתְפַּלֵּל"],0,"נָשִׁים וּבָנוֹת פְּטוּרוֹת מֵעַרְבִית: עַרְבִית הָיְתָה מִתְּחִלָּה רְשׁוּת, וְרַק הַגְּבָרִים קִבְּלוּ אוֹתָהּ עֲלֵיהֶם כְּחוֹבָה. וְגַם לְדַעַת הַסּוֹבְרִים שֶׁנָּשִׁים חַיָּבוֹת בַּתְּפִלּוֹת שֶׁתִּקְּנוּ חֲכָמִים – הַכַּוָּנָה לְשַׁחֲרִית וּלְמִנְחָה.","פֶּרֶק כ״ה, הֲלָכָה ב׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["הַשֶּׁמֶשׁ עוֹמֶדֶת לִשְׁקֹעַ. אוּרִיאֵל יָכוֹל לְהִתְפַּלֵּל מִנְחָה לְבַד עַכְשָׁו, אוֹ בְּמִנְיָן שֶׁיַּתְחִיל אַחֲרֵי הַשְּׁקִיעָה. מָה עָדִיף לְדַעַת רֹב הַפּוֹסְקִים?",["לְהִתְפַּלֵּל עַכְשָׁו לְבַד, כִּי אַחֲרֵי הַשְּׁקִיעָה אִי אֶפְשָׁר בִּכְלָל","לְהִתְפַּלֵּל בְּמִנְיָן, גַּם אִם זֶה אַחֲרֵי הַשְּׁקִיעָה","לְדַלֵּג עַל מִנְחָה, וּלְהִתְפַּלֵּל עַרְבִית פַּעֲמַיִם בַּמִּנְיָן","לְהִתְפַּלֵּל פַּעֲמַיִם: לְבַד עַכְשָׁו, וְשׁוּב יַחַד עִם הַמִּנְיָן"],1,"יֵשׁ אוֹמְרִים שֶׁעָדִיף לְהִתְפַּלֵּל לְבַד לִפְנֵי הַשְּׁקִיעָה, אֲבָל לְדַעַת רֹב הַפּוֹסְקִים עָדִיף לְהִתְפַּלֵּל בְּצִבּוּר אַחֲרֵי הַשְּׁקִיעָה. וּמִי שֶׁיָּכוֹל לְהִתְפַּלֵּל מִנְחָה – לֹא מְדַלֵּג עָלֶיהָ.","פֶּרֶק כ״ד, הֲלָכָה ד׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["בְּשַׁבַּת קַיִץ הִתְפַּלְּלוּ בְּבֵית הַכְּנֶסֶת שֶׁל שַׁי עַרְבִית מֻקְדֶּמֶת, לִפְנֵי הַשְּׁקִיעָה. מָה עָלָיו לִזְכֹּר לַעֲשׂוֹת אַחַר כָּךְ?",["לְהִתְפַּלֵּל שׁוּב תְּפִלַּת עַרְבִית שְׁלֵמָה אַחֲרֵי צֵאת הַכּוֹכָבִים","לִקְרֹא שׁוּב אֶת שָׁלֹשׁ פָּרָשִׁיּוֹת שְׁמַע אַחֲרֵי צֵאת הַכּוֹכָבִים","שׁוּם דָּבָר, כִּי הוּא כְּבָר קָרָא שְׁמַע בַּתְּפִלָּה בְּבֵית הַכְּנֶסֶת","לוֹמַר רַק ״בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ״ לִפְנֵי שֶׁהוּא נִרְדָּם"],1,"לְפִי רַבִּי יְהוּדָה אֶפְשָׁר לְהִתְפַּלֵּל עַרְבִית כְּבָר מִ״פְּלַג הַמִּנְחָה״, אֲבָל זְמַן קְרִיאַת שְׁמַע שֶׁל לַיְלָה הוּא רַק מִצֵּאת הַכּוֹכָבִים. לָכֵן קוֹרְאִים שׁוּב אֶת שָׁלֹשׁ הַפָּרָשִׁיּוֹת אַחֲרֵי צֵאת הַכּוֹכָבִים.","פֶּרֶק כ״ה, הֲלָכָה ו׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["אֶלְעָזָר נִכְנַס לְעַרְבִית בְּדִיּוּק כְּשֶׁהַצִּבּוּר מַתְחִיל שְׁמוֹנֶה עֶשְׂרֵה. מָה יַעֲשֶׂה?",["יַתְחִיל מִ״בָּרְכוּ״ וְיִתְפַּלֵּל לְבַד כַּסֵּדֶר, כְּמוֹ בְּשַׁחֲרִית","יִתְפַּלֵּל עֲמִידָה עִם הַצִּבּוּר, וְאַחַר כָּךְ יַשְׁלִים קְרִיאַת שְׁמַע","יְוַתֵּר עַל קְרִיאַת שְׁמַע, כִּי הוּא כְּבָר מְאַחֵר מְאוֹד","יְחַכֶּה שֶׁהַצִּבּוּר יְסַיֵּם, וְאָז יִתְפַּלֵּל לְבַד אֶת כָּל עַרְבִית"],1,"בְּעַרְבִית הַתְּפִלָּה בְּמִנְיָן קוֹדֶמֶת לִסְמִיכַת גְּאֻלָּה לִתְפִלָּה. לָכֵן מִתְפַּלְּלִים עֲמִידָה עִם הַצִּבּוּר, וְאַחַר כָּךְ מַשְׁלִימִים אֶת קְרִיאַת שְׁמַע וּבִרְכוֹתֶיהָ. בְּשַׁחֲרִית – מִתְפַּלְּלִים כַּסֵּדֶר.","פֶּרֶק כ״ה, הֲלָכָה ד׳","מִנְחָה, עַרְבִית וְלַיְלָה טוֹב"],["מִי יָכוֹל לָצֵאת יְדֵי חוֹבַת תְּפִלָּה בִּשְׁמִיעַת חֲזָרַת הַשַּׁ״ץ?",["מִי שֶׁיּוֹדֵעַ לְהִתְפַּלֵּל, אֲבָל מְמַהֵר מְאוֹד לַעֲבוֹדָה","מִי שֶׁאֵינוֹ יוֹדֵעַ לְהִתְפַּלֵּל וְשׁוֹמֵעַ בְּמִנְיָן","כָּל מִי שֶׁמַּקְשִׁיב הֵיטֵב, גַּם כְּשֶׁאֵין שָׁם מִנְיָן","מִי שֶׁאֵינוֹ מֵבִין עִבְרִית, אִם הוּא עוֹנֶה אָמֵן בְּקוֹל"],1,"צָרִיךְ שְׁלֹשָׁה תְּנָאִים: שֶׁאֵינוֹ יוֹדֵעַ לְהִתְפַּלֵּל, שֶׁיֵּשׁ מִנְיָן, וְשֶׁהוּא מֵבִין אֶת דִּבְרֵי הַחַזָּן. מִי שֶׁיּוֹדֵעַ – חַיָּב לְהִתְפַּלֵּל בְּעַצְמוֹ.","פֶּרֶק י״ט, הֲלָכָה ב׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["שִׁמְעוֹן שָׁכַח אֶת הַסִּדּוּר וְיוֹצֵא בִּשְׁמִיעַת הַחַזָּן. מָה הוּא אוֹמֵר וּמָה לֹא?",["עוֹנֶה אָמֵן וּקְדֻשָּׁה, אֲבָל לֹא \"בָּרוּךְ הוּא וּבָרוּךְ שְׁמוֹ\"","שׁוֹתֵק לְגַמְרֵי, וְלֹא עוֹנֶה אֲפִלּוּ אָמֵן","אוֹמֵר הַכֹּל כָּרָגִיל, וְגַם מוֹדִים דְּרַבָּנָן","עוֹנֶה רַק קְדֻשָּׁה, וְאֶת הָאָמֵן אוֹמֵר בַּסּוֹף"],0,"מִי שֶׁיּוֹצֵא בִּשְׁמִיעָה עוֹנֶה אָמֵן וּקְדֻשָּׁה, אֲבָל לֹא אוֹמֵר \"בָּרוּךְ הוּא וּבָרוּךְ שְׁמוֹ\" וְלֹא מוֹדִים דְּרַבָּנָן – כְּדֵי לֹא לְהַפְסִיק בַּתְּפִלָּה שֶׁהוּא יוֹצֵא בָּהּ.","פֶּרֶק י״ט, הֲלָכָה ב׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["לָמָּה כָּל אֶחָד צָרִיךְ לְהִזָּהֵר לַעֲנוֹת אָמֵן בַּחֲזָרָה, גַּם כְּשֶׁיֵּשׁ הַרְבֵּה אֲנָשִׁים?",["כִּי מִי שֶׁלֹּא עוֹנֶה אָמֵן חַיָּב לְהִתְפַּלֵּל שׁוּב","כִּי הַחַזָּן לֹא מַמְשִׁיךְ עַד שֶׁכֻּלָּם עוֹנִים בְּקוֹל","כִּי כָּל אֶחָד יַחְשֹׁב כְּאִלּוּ אֵין תִּשְׁעָה חוּץ מִמֶּנּוּ","כִּי רַק הָעוֹנֶה אָמֵן נֶחְשָׁב כְּמִי שֶׁהִגִּיעַ לְמִנְיָן"],2,"צָרִיךְ תִּשְׁעָה שֶׁיַּעֲנוּ אָמֵן עַל בִּרְכוֹת הַחַזָּן. כְּדֵי לֹא לְהִכָּנֵס לְסָפֵק, כָּל אֶחָד חוֹשֵׁב שֶׁאוּלַי הוּא הַתָּשִׁיעִי – וְעוֹנֶה.","פֶּרֶק י״ט, הֲלָכָה ד׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["קְרִיאַת שְׁמַע אֶפְשָׁר לוֹמַר בְּכָל שָׂפָה. וּבִרְכַּת כֹּהֲנִים?",["בְּכָל שָׂפָה שֶׁהַקָּהָל מֵבִין, כְּדֵי שֶׁיְּכַוְּנוּ","רַק בִּלְשׁוֹן הַקֹּדֶשׁ, כְּמוֹ שֶׁכָּתוּב בַּתּוֹרָה","בִּלְשׁוֹן הַקֹּדֶשׁ, וְאַחַר כָּךְ גַּם בְּתַרְגּוּם לַקָּהָל","בְּכָל שָׂפָה, בִּתְנַאי שֶׁהַכֹּהֲנִים עוֹמְדִים וּפוֹרְשִׂים כַּפַּיִם"],1,"\"כֹּה תְבָרֲכוּ\" – בַּלָּשׁוֹן הַזּוֹ שֶׁכְּתוּבָה בַּתּוֹרָה. בִּרְכַּת כֹּהֲנִים בָּאָה מִן ה׳, וְלָכֵן אוֹמְרִים אוֹתָהּ בְּדִיּוּק בִּלְשׁוֹן הַקֹּדֶשׁ.","פֶּרֶק כ׳, הֲלָכָה ד׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["בַּמִּנְיָן הַיּוֹם יֵשׁ רַק כֹּהֵן אֶחָד. מָה הַדִּין?",["אֵין בִּרְכַּת כֹּהֲנִים, כִּי צָרִיךְ לְפָחוֹת שְׁנֵי כֹּהֲנִים","קוֹרְאִים לוֹ \"כֹּהֲנִים\" בְּקוֹל רָם, כְּמוֹ בְּכָל יוֹם","הוּא מְבָרֵךְ לְבַד, בְּלִי שֶׁהַחַזָּן יַקְרִיא לוֹ מִלִּים","לֹא קוֹרְאִים \"כֹּהֲנִים\", וְהוּא עוֹלֶה וּמְבָרֵךְ"],3,"\"אָמוֹר לָהֶם\" – לְשׁוֹן רַבִּים, וְלָכֵן קוֹרְאִים \"כֹּהֲנִים\" רַק כְּשֶׁיֵּשׁ לְפָחוֹת שְׁנַיִם. כֹּהֵן אֶחָד עוֹלֶה וּמְבָרֵךְ בְּלִי הַקְּרִיאָה.","פֶּרֶק כ׳, הֲלָכָה ז׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["כֹּהֵן כָּעַס מְאוֹד עַל אָדָם אֶחָד בְּבֵית הַכְּנֶסֶת וְשׂוֹנֵא אוֹתוֹ. מָה עָלָיו לַעֲשׂוֹת?",["לְבָרֵךְ כָּרָגִיל, כִּי ה׳ הוּא הַמְבָרֵךְ וְלֹא הוּא","לִמְחוֹת אֶת הַשִּׂנְאָה מִלִּבּוֹ, אוֹ לָצֵאת לִפְנֵי הַבְּרָכָה","לְבָרֵךְ אֶת כֻּלָּם, וּלְדַלֵּג עַל הָאָדָם שֶׁהוּא כּוֹעֵס עָלָיו","לְבַקֵּשׁ מִן הָאָדָם הַהוּא לָצֵאת מִבֵּית הַכְּנֶסֶת"],1,"הַכֹּהֲנִים מְבָרְכִים \"בְּאַהֲבָה\", וְכֹהֵן שֶׁשּׂוֹנֵא אֲפִלּוּ אָדָם אֶחָד – אָסוּר לוֹ לְבָרֵךְ. עָלָיו לִמְחוֹת אֶת הַשִּׂנְאָה מִלִּבּוֹ, אוֹ לָצֵאת לִפְנֵי בִּרְכַּת כֹּהֲנִים.","פֶּרֶק כ׳, הֲלָכָה ט׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["כֹּהֵן שֶׁאֵינוֹ מַקְפִּיד עַל כָּל הַמִּצְווֹת – הַאִם יַעֲלֶה לְבָרֵךְ?",["לֹא, כִּי רַק צַדִּיק רָאוּי לְבָרֵךְ אֶת הָעָם","רַק אִם הַקָּהָל מַסְכִּים לָזֶה לִפְנֵי הַתְּפִלָּה","כֵּן, כִּי ה׳ הוּא הַמְבָרֵךְ אֶת עַמּוֹ יִשְׂרָאֵל","רַק בְּשַׁבָּתוֹת וּבַחַגִּים, וְלֹא בִּימוֹת הַחֹל"],2,"הַמִּצְוָה חָלָה עַל כָּל הַכֹּהֲנִים. \"אֵין אוֹמְרִים לְאָדָם רָשָׁע: הוֹסֵף עוֹד רֶשַׁע וְהִמָּנַע מִן הַמִּצְווֹת\". הַבְּרָכָה תְּלוּיָה בִּרְצוֹן ה׳ – לֹא בְּצִדְקוּת הַכֹּהֵן.","פֶּרֶק כ׳, הֲלָכָה י׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["לָמָּה כֹּהֵן שֶׁמְּסָרֵב לַעֲלוֹת לַדּוּכָן נֶחְשָׁב כְּאִלּוּ בִּטֵּל שָׁלֹשׁ מִצְווֹת?",["כִּי הוּא גַּם מְדַבֵּר, גַּם יוֹשֵׁב וְגַם לֹא נוֹטֵל יָדַיִם","כִּי ה׳ צִוָּה שָׁלֹשׁ פְּעָמִים, וְהוּא מִתְאַוֶּה לְבָרֵךְ","כִּי בַּבְּרָכָה יֵשׁ שְׁלֹשָׁה פְּסוּקִים, וְהוּא בִּטֵּל אֶת כֻּלָּם","כִּי הוּא מַפְסִיד שָׁלֹשׁ תְּפִלּוֹת שֶׁל אוֹתוֹ הַיּוֹם"],1,"הַתּוֹרָה אוֹמֶרֶת שָׁלֹשׁ פְּעָמִים \"כֹּה תְבָרֲכוּ\", \"אָמוֹר לָהֶם\", \"וְשָׂמוּ אֶת שְׁמִי\" – כִּי ה׳ מִתְאַוֶּה לְבָרֵךְ אֶת יִשְׂרָאֵל. מִי שֶׁמְּסָרֵב נֶחְשָׁב כְּאִלּוּ בִּטֵּל שָׁלֹשׁ מִצְווֹת.","פֶּרֶק כ׳, הֲלָכָה א׳","שׁוֹמְעִים, עוֹנִים וּמִתְבָּרְכִים"],["מֹשֶׁה רַבֵּנוּ הִתְפַּלֵּל לְהִכָּנֵס לָאָרֶץ, וְה׳ אָמַר לוֹ \"רַב לָךְ\". מָה לוֹמְדִים מִזֶּה?",["שֶׁתְּפִלָּה שֶׁל צַדִּיק גָּדוֹל תָּמִיד מִתְקַבֶּלֶת מִיָּד","שֶׁאֵין טַעַם לְהִתְפַּלֵּל עַל דְּבָרִים שֶׁל עַצְמֵנוּ","שֶׁה׳ שׁוֹמֵעַ, גַּם כְּשֶׁאֵינוֹ נוֹתֵן מָה שֶׁבִּקַּשְׁנוּ","שֶׁצָּרִיךְ לְהִתְפַּלֵּל רַק בִּזְמַן שֶׁל צָרָה גְּדוֹלָה מְאוֹד"],2,"גַּם תְּפִלּוֹת שֶׁל צַדִּיקִים לִפְעָמִים לֹא נִתְקַבְּלוּ. לָכֵן מַמְשִׁיכִים לְהִתְפַּלֵּל, וְיוֹדְעִים שֶׁה׳ שׁוֹמֵעַ וְהַתְּפִלָּה פּוֹעֶלֶת לְטוֹבָה – גַּם כְּשֶׁאֵין אָנוּ יוֹדְעִים אֵיךְ.","פֶּרֶק א׳, הֲלָכָה ג׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["לָמָּה תִּקְּנוּ אַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה נֻסָּח קָבוּעַ לַתְּפִלָּה?",["כְּדֵי שֶׁכֻּלָּם יִתְפַּלְּלוּ כָּרָאוּי, עַל כָּל הַצְּרָכִים","כְּדֵי שֶׁהַתְּפִלָּה תִּהְיֶה קְצָרָה וְלֹא תַּטְרִיחַ אֶת הָעָם","כִּי בִּזְמַנָּם כְּבָר לֹא הָיוּ צַדִּיקִים שֶׁמִּתְפַּלְּלִים מֵהַלֵּב","כְּדֵי שֶׁיִּהְיֶה אֶפְשָׁר לְהִתְפַּלֵּל רַק בְּבֵית הַמִּקְדָּשׁ"],0,"בְּלִי נֻסָּח, הַצַּדִּיקִים הִתְפַּלְּלוּ יָפֶה – אֲבָל רֹב הָעָם הִתְפַּלֵּל בְּחִפָּזוֹן וּבְשִׁבּוּשִׁים, וְכָל אֶחָד רַק עַל מָה שֶׁקָּרוֹב לְלִבּוֹ. הַנֻּסָּח מְלַמֵּד אֶת כֻּלָּם לְבַקֵּשׁ עַל הַכֹּל.","פֶּרֶק א׳, הֲלָכוֹת ה׳–ו׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["יְהוּדִי שֶׁעָלָה לָאָרֶץ וְאֵינוֹ מֵבִין עִבְרִית – הַאִם יָכוֹל לְהִתְפַּלֵּל בִּשְׂפָתוֹ?",["לֹא, תְּפִלָּה בְּכָל מַצָּב רַק בִּלְשׁוֹן הַקֹּדֶשׁ","כֵּן, וְכָךְ כְּדַאי שֶׁיִּתְפַּלְּלוּ כָּל הַקְּהִלּוֹת תָּמִיד","כֵּן, וְהוּא יוֹצֵא כִּי הוּא מֵבִין","רַק אִם יֵשׁ אִתּוֹ מִנְיָן שֶׁמִּתְפַּלֵּל בְּעִבְרִית"],2,"מִי שֶׁאֵינוֹ מֵבִין עִבְרִית יוֹצֵא יְדֵי חוֹבָה בְּשָׂפָה שֶׁהוּא מֵבִין. אֲבָל אָסוּר לִקְבֹּעַ מִנְיָן שֶׁתָּמִיד יִתְפַּלְּלוּ בּוֹ בְּשָׂפָה אַחֶרֶת.","פֶּרֶק א׳, הֲלָכָה י׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["חַזָּן אַשְׁכְּנַזִּי עוֹבֵר לִפְנֵי הַתֵּבָה בְּבֵית כְּנֶסֶת סְפָרַדִּי. בְּאֵיזֶה נֻסָּח יִתְפַּלֵּל?",["בְּנֻסַּח אֲבוֹתָיו, כִּי אָסוּר לְשַׁנּוֹת מִמִּנְהַג אָבוֹת","בְּנֻסַּח הַקָּהָל, כִּי הוּא מִתְפַּלֵּל בִּשְׁלִיחוּתָם","חֲצִי בְּנֻסָּח שֶׁלּוֹ וַחֲצִי בְּנֻסַּח הַקָּהָל","בְּאֵיזֶה נֻסָּח שֶׁהוּא רוֹצֶה, הָעִקָּר שֶׁיְּכַוֵּן"],1,"הַחַזָּן הוּא שְׁלִיחַ הַצִּבּוּר, וְלָכֵן הוּא מִתְפַּלֵּל כְּמִנְהַג הַקָּהָל שֶׁשָּׁלַח אוֹתוֹ.","פֶּרֶק ו׳, הֲלָכָה ה׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["חַזָּן סְפָרַדִּי אוֹמֵר בְּתַחֲנוּן שֶׁל שֵׁנִי וַחֲמִישִׁי שָׁלֹשׁ פְּעָמִים י״ג מִדּוֹת. מָה יַעֲשֶׂה הָאַשְׁכְּנַזִּי?",["יַמְשִׁיךְ בְּתַחֲנוּן שֶׁלּוֹ, כִּי כָּל אֶחָד כְּנֻסָּחוֹ","יֵצֵא מִבֵּית הַכְּנֶסֶת עַד שֶׁהַחַזָּן יְסַיֵּם","יַפְסִיק וְיַעֲנֶה אַחֲרָיו י״ג מִדּוֹת רַחֲמִים","יֹאמַר בְּקוֹל רָם אֶת הַנֻּסָּח הָאַשְׁכְּנַזִּי שֶׁלּוֹ"],2,"כְּשֶׁחַזָּן סְפָרַדִּי אוֹמֵר י״ג מִדּוֹת רַחֲמִים, רָאוּי שֶׁגַּם הָאַשְׁכְּנַזִּים יַפְסִיקוּ וְיַעֲנוּ אַחֲרָיו. וּבַחֲלָקִים שֶׁבְּשֶׁקֶט – כָּל אֶחָד כְּמִנְהָגוֹ.","פֶּרֶק ו׳, הֲלָכָה ט׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["בַּבֹּקֶר, לִפְנֵי הַתְּפִלָּה, יוֹסֵף עוֹבֵר לְיַד בֵּית סָבָא, וּמִנִּימוּס נִכְנָס לְבָרֵךְ אוֹתוֹ. מָה יֹאמַר?",["\"שָׁלוֹם, סָבָא!\" – כִּי זוֹ בְּרָכָה יָפָה וּמְכֻבֶּדֶת","\"בֹּקֶר טוֹב, סָבָא!\" – וְלֹא \"שָׁלוֹם\"","שׁוֹתֵק, כִּי אָסוּר לְדַבֵּר כְּלָל לִפְנֵי הַתְּפִלָּה","\"שָׁלוֹם\" – אֲבָל רַק אַחֲרֵי שֶׁיֹּאמַר בִּרְכוֹת הַשַּׁחַר"],1,"\"שָׁלוֹם\" הוּא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא מְכַבְּדִים בּוֹ אָדָם לִפְנֵי הַתְּפִלָּה. לָכֵן אוֹמְרִים \"בֹּקֶר טוֹב\".","פֶּרֶק י״ב, הֲלָכָה א׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["יוֹם שִׁשִּׁי בַּבֹּקֶר. אַבָּא חוֹשֵׁשׁ שֶׁאַחֲרֵי הַתְּפִלָּה לֹא יִשָּׁאֵר בַּחֲנוּת אֹכֶל לְשַׁבָּת. מָה הַדִּין?",["מֻתָּר לִקְנוֹת לִפְנֵי הַתְּפִלָּה, כִּי זֶה צֹרֶךְ מִצְוָה","אָסוּר, כִּי אָסוּר לַעֲסֹק בְּשׁוּם דָּבָר לִפְנֵי הַתְּפִלָּה","מֻתָּר, וְאָז מֻתָּר לִקְנוֹת גַּם דְּבָרִים אֲחֵרִים לַבַּיִת","מֻתָּר רַק אִם יִתְפַּלֵּל אַחַר כָּךְ בְּמִנְיָן"],0,"צָרְכֵי מִצְוָה מֻתָּרִים לִפְנֵי הַתְּפִלָּה, וְאֹכֶל לְשַׁבָּת הוּא צֹרֶךְ מִצְוָה. אֲבָל דְּבָרִים שֶׁאֵינָם לְצֹרֶךְ מִצְוָה – אֲפִלּוּ דָּבָר אֶחָד אָסוּר לִקְנוֹת.","פֶּרֶק י״ב, הֲלָכָה ג׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"],["קָרְבַּן הַתָּמִיד נִקְנָה מִכַּסְפֵּי מַחֲצִית הַשֶּׁקֶל שֶׁל כָּל יְהוּדִי. מָה זֶה מְבַטֵּא?",["שֶׁהָעֲשִׁירִים צְרִיכִים לָתֵת הַרְבֵּה יוֹתֵר מִן הָעֲנִיִּים","אֶת אַחְדוּת יִשְׂרָאֵל – כֻּלָּם שֻׁתָּפִים בַּקָּרְבָּן","שֶׁהַקָּרְבָּן שַׁיָּךְ רַק לַכֹּהֲנִים שֶׁמַּקְרִיבִים אוֹתוֹ","שֶׁכָּל אֶחָד מֵבִיא קָרְבָּן פְּרָטִי מִשֶּׁלּוֹ"],1,"כָּל יְהוּדִי, עָנִי וְעָשִׁיר, נָתַן מַחֲצִית הַשֶּׁקֶל – וְכָךְ כָּל יִשְׂרָאֵל הָיוּ שֻׁתָּפִים בַּתָּמִיד. הוּא מְבַטֵּא אֶת אַחְדוּת יִשְׂרָאֵל וְאֶת הַקֶּשֶׁר הַקָּבוּעַ עִם ה׳.","פֶּרֶק י״ג, הֲלָכָה ה׳","מִתְכּוֹנְנִים לְשַׁחֲרִית"]]};